controller: webviewController
})
.zoomAccess(false)
.onLoadIntercept((event) => {
const url: string = event.data.getRequestUrl();
if (url === 'ark

从API version 11及以上版本，支持通过配置文件开发意图。主要包含两个环节： 通过 insight_intent.json配置文件 定义意图，声明意图执行器的代码路径、绑定的Ability组件等意图信息。 通过 InsightIntentExecutor 实现意图执行逻辑。 不同Ability组件类型需要配置的字段与需要实现的意图执行器，如下所示： 当"executeMode"字段为"foreground"时，实现onExecuteInUIAbilityForegroundMode，通过startAbility启动意图绑定的UIAbility组件。 当"executeMode"字段为"background"时，实现onExecuteInUIAbilityBackgroundMode，通过 Call调用 启动意图绑定的UIAbility组件。 意图执行器实现需要继承 InsightIntentExecutor ，实现 onExecuteInUIAbilityForegroundMode 等方法。开发者响应意图执行通过onExecuteInUIAbilityForegroundMode等接口实现，在不同的意图执行模式下，接口的触发时机也不同。针对不同意图执行模式的意图回调执行时机见各个回调的API说明。 通过DevEco Studio工具可视化创建意图，操作及开发步骤如下。 选中模块或模块下的文件，右键单击New > Insight Intent，进入意图框架配置界面。 选择意图垂域、意图框架入口代码文件名以及意图配置。意图配置包含意图名称和绑定的Ability组件。 点击Finish，完成意图框架创建。 此时将在module目录 > src > main > resources > base > profile中，生成insight_intent.json文件，可在该文件查看当前意图框架配置的相关信息。 {
"insightIntents": [
{
"domain": "MusicDomain",
"intentName": "PlayMusic",
"intentVersion": "1.0.1",
"srcEntry": "./ets/insightintents/PlayMusicExecutor.ets",
"uiAbility": {
"ability": "MusicPlayerAbility",
"executeMode": [
"foreground",
"background"
]
}
}
]
}

从 API version 20开始，支持通过装饰器开发意图，支持将现有功能通过装饰器快速集成至系统入口。典型场景介绍如下。 - 通过 @InsightIntentEntry 创建新的意图逻辑，绑定UIAbility组件或UIExtensionAbility组件。 - 通过 @InsightIntentLink 将uri链接转换为意图。 - 通过 @InsightIntentPage 将页面路由转换为意图。 - 通过 @InsightIntentFunctionMethod 将函数调用转换为系统意图。 - 通过 @InsightIntentEntry 创建新的意图逻辑，绑定UIAbility组件的后台执行模式或ServiceExtensionAbility组件。 1. 开发者新增意图执行文件，若该执行文件未被其他文件导入，需要通过insight_intent.json文件的"insightIntentsSrcEntry"字段配置意图执行文件路径，使其参与编译。 2. 通过装饰器定义意图需要绑定Ability组件、定义意图执行模式。 1. 系统入口通过startAbility启动意图绑定的UIAbility组件。若意图未绑定UIAbility组件，则启动意图所在module的 mainElement 对应的UIAbility组件。 2. 意图执行时，若应用未启动，在UIAbility的首页加载后跳转到意图对应的页面；若应用已启动，由当前页面跳转到意图对应的页面。 3. 意图执行时，参数会被传递给目标页面。 4. "navigationId"字段或"navDestinationName"字段匹配失败时，退化为"pagePath"字段对应的页面跳转。 本章节以通过@InsightIntentEntry开发标准意图和自定义意图举例，其他装饰器开发标准意图和自定义意图与@InsightIntentEntry相似，可以结合API参考开发其他类型的意图。 以通过@InsightIntentEntry装饰器开发 查看快递 标准意图举例。 在insight_intent.json配置文件中的"insightIntentsSrcEntry"字段声明意图执行文件。 {
"insightIntentsSrcEntry": [
{
"srcEntry": "./ets/insightintents/ViewLogisticsImpl.ets"
}
]
}

在跨应用协作场景下，开发者经常需要从系统应用调用其他应用提供的智能体服务，但缺少标准化的通信机制，导致集成成本高、安全认证复杂。从API version 24开始，支持开发者使用 AgentExtensionAbility 类型的组件提供智能体服务。系统应用可以连接其他应用实现的 AgentExtensionAbility 组件，并使用相应的智能体服务。通过使用该组件，可降低跨应用对接成本，保障通信安全，同时支持双向数据通道实时交互。 本文描述中称被连接的 AgentExtensionAbility 为服务端，称连接 AgentExtensionAbility 的组件为客户端。 在DevEco Studio工程中手动新建一个 AgentExtensionAbility ，具体步骤如下： 在工程Module对应的ets目录下，右键选择"New > Directory"，新建一个目录并命名为agentextability。 在AgentExtAbility目录，右键选择"New > ArkTS File"，新建一个文件并命名为AgentExtAbility.ets。 ├── ets
│ ├── agentextability
│ │ ├── AgentExtAbility.ets 在AgentExtAbility目录，右键选择"New > ArkTS File"，新建一个文件并命名为AgentExtAbility.ets。 在AgentExtAbility.ets文件中，补充 AgentExtensionAbility 的导入模块，自定义类AgentExtAbility继承 AgentExtensionAbility 并实现生命周期回调。 import { common, AgentExtensionAbility, Want } from '@kit.AbilityKit';
