let result = a - b;
this.newCalc(`${a} - ${b}`, `${result}`);
return result;
}

// 乘法运算
mul(a: number, b: number) {
let result = a * b;
this.newCalc(`${a} * ${b}`, `${result}`);
return result;
}

// 除法运算
