// 打印历史

对于需要使用进程单例的场景，例如不同并发实例间需要数据保持一致的全局配置项功能，可以采用 共享模块 来实现。 以下示例展示了只有在Wi-Fi打开且用户登录的情况下才能进行下载的功能，具体步骤如下。 编写全局配置文件。 import { ArkTSUtils } from '@kit.ArkTS';

'use shared'

@Sendable
class Config {
public lock: ArkTSUtils.locks.AsyncLock = new ArkTSUtils.locks.AsyncLock();
public isLogin: boolean = false;
public loginUser?: string;
public wifiOn: boolean = false;

async login(user: string) {
return this.lock.lockAsync(() => {
this.isLogin = true;
this.loginUser = user;
}, ArkTSUtils.locks.AsyncLockMode.EXCLUSIVE)
}

async logout(user?: string) {
return this.lock.lockAsync(() => {
this.isLogin = false;
this.loginUser = '';
}, ArkTSUtils.locks.AsyncLockMode.EXCLUSIVE)
}

async getIsLogin(): Promise<boolean> {
return this.lock.lockAsync(() => {
return this.isLogin;
}, ArkTSUtils.locks.AsyncLockMode.SHARED)
}

async getUser(): Promise<string> {
return this.lock.lockAsync(() => {
return this.loginUser!;
}, ArkTSUtils.locks.AsyncLockMode.SHARED)
}

async setWifiState(state: boolean) {
return this.lock.lockAsync(() => {
this.wifiOn = state;
}, ArkTSUtils.locks.AsyncLockMode.EXCLUSIVE)
}

async isWifiOn() {
