Row() {
Column() {
Text(this.message)
.fontSize(50)
.fontWeight(FontWeight.Bold)
.onClick(() => {
console.info('test start');
// 其他业务逻辑
// ...
let task: taskpool.Task = new taskpool.Task(createTask, 1, 2);
taskpool.execute(task);
// ...
})
}
.width('100%')
}
.height('100%')
}
}

