OH_ArkUI_QueryModuleInterfaceByName(ARKUI_NATIVE_GESTURE, "ArkUI_NativeGestureAPI_1"));
// 创建长按手势
// DURATION_NUM_1000 = 1000
auto longPressGesture = gestureApi->createLongPressGesture(1, true, DURATION_NUM_1000);

