@Entry
@Component
struct WebComponent {
controller: webview.WebviewController = new webview.WebviewController();

build() {
Column() {
Web({ src: 'www.example.com', controller: this.controller })
.width('100%').height('100%')
}
}
}

Web组件的长截图功能可以对网页内容进行截图，旨在为用户提供快速便捷的数据信息分享和保存方式，确保用户能够完整地捕获和分享浏览的网页信息。 点击“一键截图”按钮即可完成整个网页的长截图，并可将截图保存至相册。 Web组件可以通过滚动截图方案以及使用WebView提供的 webPageSnapshot 进行长截图。其中WebView提供的webPageSnapshot方法比较适合结构简单、静态元素的页面长截图，如果网页中有动态资源，结构相对复杂，比如有固定的标题头等，推荐使用滚动截图方案。 Web组件滚动长截图和 滚动组件长截图 开发流程大体一样，主要是控制组件的滚动的方法不同。List组件使用的是 Scroller ，而Web组件使用的是 webViewController 。 在滚动截图过程中，webViewController负责控制Web组件的滚动，通过调用 webViewController.scrollBy 方法来实现。为了判断是否已滚动到底部，使用this.webViewController.getPageHeight() 方法获取网页内容的总高度，详情可参考 获取网页内容高度 ，并将当前偏移量this.curYOffset加上组件自身的高度与网页总高度进行比较。如果两者的和小于网页总高度，则表示尚未触底。 使用webPageSnapshot()方法进行网页长截图 Web组件使用 webPageSnapshot() 方法实现长截图的步骤如下： Web初始化，调用enableWholeWebPageDrawing()方法开启网页全量绘制能力。 aboutToAppear(): void {
try {
webview.WebviewController.initializeWebEngine();
webview.WebviewController.enableWholeWebPageDrawing();
webview.WebviewController.prepareForPageLoad(EXAMPLE_URL, true, 2);
} catch (err) {
let error = err as BusinessError;
Logger.error(TAG, `web snapshot init err, errCode: ${error.code}, error message: ${error.message}`);
}
}

Web组件支持使用DevTools工具调试前端页面。DevTools是Web前端开发调试工具，支持在电脑上调试移动设备前端页面。开发者通过 setWebDebuggingAccess() 接口开启Web组件前端页面调试能力，使用DevTools在电脑上调试移动前端网页，设备需为4.1.0及以上版本。 从API version 20开始，可使用无线调试接口 setWebDebuggingAccess 20+ ，来简化调试流程。 调试网页前，需要应用侧代码调用setWebDebuggingAccess()接口开启Web调试开关。 如果没有开启Web调试开关，则DevTools无法发现被调试的网页。 在应用代码中开启Web调试开关，应用需要调用 setWebDebuggingAccess 20+ 接口，设置TCP Socket端口号并启用Web调试功能。 import { webview } from '@kit.ArkWeb';
import { BusinessError } from '@kit.BasicServicesKit';
const DEBUGGING_PORT: number = 8888;

@Entry
@Component
struct WebComponent {
controller: webview.WebviewController = new webview.WebviewController();

aboutToAppear(): void {
try {
// 配置Web开启无线调试模式，指定TCP Socket的端口。
webview.WebviewController.setWebDebuggingAccess(true, DEBUGGING_PORT);
} catch (error) {
console.error(`ErrorCode: ${(error as BusinessError).code}, Message: ${(error as BusinessError).message}`);
}
}

build() {
Column() {
Web({ src: 'www.example.com', controller: this.controller })
}
}
} 代码中使用的8888端口仅作为示例展示，开发者使用过程中，应保证端口号可以被应用使用。如果因为端口被占用或者应用无权限使用等因素导致端口无法被应用使用，会导致接口抛出异常或者ArkWeb无法开启调试模式。

Web页面出现白屏的原因众多，本文列举了若干常见白屏问题的排查步骤，供开发者快速定位。 通过 使用DevTools工具调试前端页面 定位具体报错类型（跨域、资源404、JS异常）。 在复杂布局场景中，排查渲染模式及组件约束条件的问题。 从日志中排查生命周期和网络加载相关关键字。 检查是否开启 坚盾守护模式 ，坚盾守护模式开启后相关限制见： ArkWeb限制的HTML5特性 。 如果应用未开启联网或文件访问权限或者设备网络状态不佳，将导致Web组件加载失败或页面元素缺失，进而引起白屏。 验证设备的网络状态，包括是否已连接网络，设备自带的浏览器能否正常访问网页等（在线页面场景）。 确保应用已添加网络权限：ohos.permission.INTERNET（在线页面必需）。 "requestPermissions":[
{
"name" : "ohos.permission.INTERNET"
}
], 确保应用已添加网络权限：ohos.permission.INTERNET（在线页面必需）。 开启相关权限： 名称 说明 domStorageAccess 设置是否开启文档对象模型存储接口（DOM Storage API）权限。若不开启，无法使用localStorage存储数据，任何调用localStorage的代码都将失效，依赖本地存储的功能会异常。 fileAccess 设置是否开启应用中文件系统的访问。‌若不开启，文件读写功能完全被阻断，依赖文件的模块会崩溃。 imageAccess 设置是否允许自动加载图片资源。 onlineImageAccess 设置是否允许从网络加载图片资源（通过HTTP和HTTPS访问的资源）。 javaScriptAccess 设置是否允许执行JavaScript脚本。 import { webview } from '@kit.ArkWeb';

@Entry
@Component
struct WebComponent {
controller: webview.WebviewController = new webview.WebviewController();

build() {
Column() {
Web({ src: 'www.example.com', controller: this.controller })
.domStorageAccess(true)
.fileAccess(true)
.imageAccess(true)
.onlineImageAccess(true)
.javaScriptAccess(true)
}
}
}

Web页面加载失败问题复杂多样，本文详细列举常见问题的排查方法，供开发者快速定位。 如果应用未开启联网或文件访问权限或者设备网络状态不佳，将导致Web组件加载失败。 确认设备网络状态：检查设备是否连接网络，验证内置浏览器能否正常访问网页（适用于在线页面场景）。 添加网络权限：确保应用已声明 ohos.permission.INTERNET 权限（在线页面必需）。 "requestPermissions":[
{
"name" : "ohos.permission.INTERNET"
}
], 添加网络权限：确保应用已声明 ohos.permission.INTERNET 权限（在线页面必需）。 开启相关权限： 名称 说明 domStorageAccess 设置是否开启文档对象模型存储接口（DOM Storage API）权限，若不开启，无法使用localStorage存储数据，任何调用localStorage的代码都将失效，依赖本地存储的功能会异常。 fileAccess ‌设置是否开启应用中文件系统的访问。若不开启，文件读写功能完全被阻断，依赖文件的模块会崩溃。 imageAccess 设置是否允许自动加载图片资源。 onlineImageAccess 设置是否允许从网络加载图片资源（通过HTTP和HTTPS访问的资源）。 javaScriptAccess 设置是否允许执行JavaScript脚本。 import { webview } from '@kit.ArkWeb';

@Entry
@Component
struct WebComponent {
controller: webview.WebviewController = new webview.WebviewController();

build() {
Column() {
Web({ src: 'www.example.com', controller: this.controller })
.domStorageAccess(true)
.fileAccess(true)
.imageAccess(true)
.onlineImageAccess(true)
.javaScriptAccess(true)
}
}
}

应用退至后台一小段时间后，应用进程会被挂起，无法执行对应的任务。如果应用在后台仍需要执行耗时不长的任务，如状态保存等，可以通过本文申请短时任务，扩展应用在后台的运行时间。 申请短时任务的按钮，不可连续点击超过3次，否则会超出短时任务数量限制并报错。使用过程中更多的约束与限制请参考短时任务（ArkTS）的 约束与限制 。 常用接口如下表所示，具体API说明详见 transient_task_api.h 。 封装函数 #include "napi/native_api.h"
#include "transient_task/transient_task_api.h"

TransientTask_DelaySuspendInfo delaySuspendInfo;
const int32_t TransientTask_TIMER = 3;
static void Callback(void)
{
// 短时任务即将结束，业务在这里取消短时任务
OH_BackgroundTaskManager_CancelSuspendDelay(delaySuspendInfo.requestId);
}

// 申请短时任务
static napi_value RequestSuspendDelay(napi_env env, napi_callback_info info)
{
napi_value result;
int32_t res = OH_BackgroundTaskManager_RequestSuspendDelay("test", Callback, &delaySuspendInfo);
if (res == 0) {
napi_create_int32(env, delaySuspendInfo.requestId, &result);
} else {
napi_create_int32(env, -1, &result);
}
return result;
}

// 获取剩余时间
static napi_value GetRemainingDelayTime(napi_env env, napi_callback_info info)
{
napi_value result;
int32_t delayTime = 0;
int32_t res = OH_BackgroundTaskManager_GetRemainingDelayTime(delaySuspendInfo.requestId, &delayTime);
if (res == 0) {
napi_create_int32(env, delayTime, &result);
} else {
napi_create_int32(env, -1, &result);
}
return

OH_ContentEmbed 内容嵌入模块提供对象编辑框架与技术，支持应用间文档嵌入与协同编辑。 OE客户端应用指嵌入其他文档的应用，通过调用OE框架层 content_embed_proxy.h 提供的接口实现嵌入外部文档、展示文档快照，以及按需启动OE服务端应用编辑文档的功能。 在CAD文档中嵌入Excel表格，通过点击嵌入对象启动Excel应用进行编辑。 在文档编辑器中嵌入图片、表格等多种格式的文档。 在笔记应用中嵌入其他应用的文档，实现跨应用协作。 在使用接口前，需先确认设备具备SystemCapability.ContentEmbed.ObjectEditor系统能力，判断方式请参阅 canIUse() 接口查询指定的系统能力是否被支持。并申请ohos.permission.CONNECT_OBJECTEDITOR_EXTENSION权限，配置方式请参阅 声明权限 。 常用接口如下表所示。更多API说明请参考 OH_ContentEmbed 。 以下演示使用Native API开发OE客户端应用的完整流程。 CMakeLists.txt中添加以下lib。 查询当前设备在指定语言下支持的所有可嵌入文档的信息。 基于OEID创建OE文档 void CreateDocumentByOEid(const std::string &oeid)
{
ContentEmbed_Document* ceDocument = nullptr;
// 基于OEID创建OE文件
ContentEmbed_ErrorCode errCode = OH_ContentEmbed_CreateDocumentByOEid(oeid.c_str(), &ceDocument);
} 基于文件创建OE文档 void CreateDocumentByFile(std::string filePath)
{
// 基于文件创建OE文档
ContentEmbed_Document *ceDocument = nullptr;
// 是否以链接形式创建OE文档，当isLinking为true时，表示以链接方式创建OE文档；当isLinking为false时，表示以嵌入方式创建OE文档。
bool isLinking = false;
ContentEmbed_ErrorCode ret = OH_ContentEmbed_CreateDocumentByFile(filePath.c_str(), filePath.size(), isLinking, &ceDocument);
}

