}
// 用于区分系统时间和系统时制变化
if (data.data != undefined && data.data == '24HourChange') {
console.info('The subscribe

在不同的国家和文化中，数字、货币和度量衡的表示方法各异，包括小数分隔符、小数位数、货币和度量衡单位等。例如，应用界面需要显示数字“1,000”（一千）表示商品价格。若采用固定格式“1,000”，在欧洲某些国家（如德国）用户会将其理解为“1”，因为这些国家使用逗号作为小数分隔符。为了确保界面符合当地习惯，需要对数字、货币和度量衡进行格式化，使其根据用户的语言和地区设置显示。 数字格式化请参考 Intl.NumberFormat 。 数字范围格式化请参考 formatRange 。 货币和单位的格式化基于数字格式化，在创建货币和单位格式化对象时，将数字的显示风格分别设置为“currency(货币)”和“unit(单位)”。同样，对货币和度量衡进行格式化时也支持通过 Intl.NumberFormatOptions 设置不同的格式。 度量衡包括长度单位、面积单位、体积单位和容量单位等，通过 I18NUtil 类的 unitConvert 接口实现度量衡转换和格式化。 unitConvert接口可以将原始单位转换为目标单位，并根据区域ID格式化。通过style参数可以控制格式化风格。 以原始单位为美制单位cup，目标单位为公制单位liter，数字大小1000为例。 导入模块。 import { i18n } from '@kit.LocalizationKit'; 单位转换。 // 设置要转换的单位和目标单位
let fromUnit: i18n.UnitInfo = {unit: 'cup', measureSystem: 'US'};
let toUnit: i18n.UnitInfo = {unit: 'liter', measureSystem: 'SI'};

// 以en-US区域ID转换度量衡
let simplifyConvertedUnit = i18n.I18NUtil.unitConvert(fromUnit, toUnit, 1000, 'en-US'); // simplifyConvertedUnit = '236.588 L'

// 显示完整的度量衡
let convertedUnit = i18n.I18NUtil.unitConvert(fromUnit, toUnit, 1000, 'en-US', 'long'); // convertedUnit = '236.588 liters'

不同国家和地区的电话号码在号码位数、组合方式、呈现方式等都存在差异。同时，在不同环境和条件下，电话号码可能存在不同的拨打方式和号码格式。例如，在中国境内跨地区打电话，通常需要先输入“0”，再拨打区号和八位电话号码，而在香港或澳门拨打电话时，需要不同的拨号方式。 通过号码格式化，可以根据需要给用户展示特定格式的电话号码。 电话号码格式化通过 PhoneNumberFormat 的 format 接口实现。 以电话号码158****2312，所属国家代码CN为例，说明PhoneNumberFormatOptions不同取值和显示效果。 导入模块。 import { i18n } from '@kit.LocalizationKit'; 处理号码。 // 格式化电话号码
let phoneNumberFormat: i18n.PhoneNumberFormat = new i18n.PhoneNumberFormat('CN');
let formattedPhoneNumber = phoneNumberFormat.format('158****2312'); // formattedPhoneNumber = '158 **** 2312'

// RFC3966类型的电话号码
let rfcFormat: i18n.PhoneNumberFormat = new i18n.PhoneNumberFormat('CN', { type: 'RFC3966' });
let formattedRFCPhoneNumber = rfcFormat.format('158****2312'); // formattedRFCPhoneNumber = 'tel:+86-158-****-2312'

// 判断电话号码是否有效
let isValid = phoneNumberFormat.isValidNumber('158****2312'); // isValid = true

// 以某种语言显示号码归属地
let locationName = phoneNumberFormat.getLocationName('158****2312', 'en-GB'); // locationName = 'XiAn, Shanxi'

// 拨号中的电话号码格式化
let typingFormat: i18n.PhoneNumberFormat = new i18n.PhoneNumberFormat('CN', { type: 'TYPING' });
let phoneNumber = '0755453';
let formatResult = ''; // 通过如下方式对拨号中的号码格式化后，formatResult = '0755 453'
for (l

不同地区的用户使用不同的历法，大多数地区使用公历，也有些地区的用户使用其他历法，例如农历、伊斯兰历或希伯来历。日历上的时间和日期根据历法计算得到，并会随时区和夏令时的变化而调整。因此，用户需要设置符合本地习惯的历法。国际化提供了 Calendar 类，可以设置历法、日期、时区、一周的起始日期和一年中第一周的最小天数。此外，还可以判断具体某一天在日历中是否为周末以及计算相差天数。在应用开发过程中，可以根据业务需求选择使用不同功能。 以查看公历日期对应的农历日期为例，说明如何使用 Calendar 类接口。 导入模块。 import { i18n } from '@kit.LocalizationKit'; 公历相关用法。 let calendar: i18n.Calendar = i18n.getCalendar('zh-Hans', 'gregory');
// 设置日历对象的时间日期为2022.06.13 08:00:00
calendar.setTime(new Date(2022, 5, 13, 8, 0, 0));
calendar.setTime(1655078400000);

// 设置日历对象的时间日期为2022.06.13 08:00:00
calendar.set(2022, 5, 13, 8, 0, 0);

// 设置日历对象的时区
calendar.setTimeZone('Asia/Shanghai');

// 获取日历对象的时区
let timezone = calendar.getTimeZone(); // timezone = 'Asia/Shanghai'

// 获取日历对象的一周起始日
let firstDayOfWeek = calendar.getFirstDayOfWeek(); // firstDayOfWeek = 1

// 设置每一周的起始日
calendar.setFirstDayOfWeek(1);

// 获取一年中第一周的最小天数
let minimalDaysInFirstWeek = calendar.getMinimalDaysInFirstWeek(); // minimalDaysInFirstWeek = 1

// 设置一年中第一周的最小天数
calendar.setMinimalDaysInFirstWeek(3);

// 获取日历对象中与field相关联的值
let year = calendar.get('year'); // year = 2022

// 获取日历对象本地化名称
let calendarName = calendar.getDisplayName('zh-Hans'); // calendarName = '公历'

// 判断指定的日期在日历中是否为

全球各国家和地区的经度不同，地方时间也有所不同，因此划分了不同的时区。例如，英国采用0时区，中国采用东8时区，中国时间要比英国快8小时，中国北京中午12:00，对应英国伦敦是凌晨4:00。时区模块可用于获取时区列表，应用可基于该列表实现业务逻辑，如双时钟应用。 从API version 20开始，时区模块还可用于获取时区跳变时间点和偏移量等，时区的跳变逻辑参考 夏令时跳变 。 时区模块关键接口如下表所示，具体API说明详见 国际化-I18n 。 导入模块。 import { i18n } from '@kit.LocalizationKit'; 时区接口基本功能：包括获取特定时区、计算固定和实际时区偏移量、遍历时区列表。 // 获取巴西时区
let timezone: i18n.TimeZone = i18n.getTimeZone('America/Sao_Paulo'); // 传入特定时区，创建时区对象
let timezoneId = timezone.getID(); // timezoneId = 'America/Sao_Paulo'

// 获取城市ID对应的时区对象
let aucklandTimezone: i18n.TimeZone = i18n.TimeZone.getTimezoneFromCity('Auckland');
timezoneId = aucklandTimezone.getID(); // timezoneId = 'Pacific/Auckland'

// 获取时区的本地化名称
let timeZoneName = timezone.getDisplayName('zh-Hans', true); // timeZoneName = '巴西利亚标准时间'

// 本地化城市名称
let cityDisplayName = i18n.TimeZone.getCityDisplayName('Auckland', 'zh-Hans'); // cityDisplayName = '奥克兰 (新西兰)'

// 时区的固定偏移量
let rawOffset = timezone.getRawOffset(); // rawOffset = -10800000

// 时区的实际偏移量（固定偏移量+夏令时）
let offset = timezone.getOffset(1234567890); // offset = -10800000

// 系统支持的时区ID列表
let availableIDs = i18n.TimeZone.getAvailableIDs(); // availableIDs = ['America/Adak', 'Asia/Hovd', ...]

// 系统支持的时区城市ID列表
