从6.0.0(20)版本开始，新增支持设置列表卡片样式。 应用使用 HdsListItemCard 组件实现多设备上的系统列表样式。 导入相关模块。 import { HdsListItemCard, PrefixImage, SuffixSwitch} from '@kit.UIDesignKit';
import { promptAction } from '@kit.ArkUI'; 创建HdsListItemCard组件，设置左边为Image，中间为Text，右边为Switch的场景。 @Entry
@Component
struct Index {
private scroller: ListScroller = new ListScroller();

build() {
Column() {
List({ space: 10, scroller: this.scroller }) {
ListItem() {
HdsListItemCard({
// A区图片
prefixItem: new PrefixImage({
image: $r('app.media.background'),
onClick: () => {
promptAction.openToast({ message: 'left image' });
}
}),
// B区文本
textItem: {
primaryText: {
text: 'Primary Text'
},
secondaryText: {
text: 'Secondary Text'
},
description: {
text: 'Description Text'
}
},
// C区Switch
suffixItem: new SuffixSwitch({
isCheck: false,
onChange: (num: boolean) => {
if (num) {
promptAction.openToast({ message: 'switch is true' });
} else {
promptAction.openToast({ message: 'switch is false' });
}
}
}),
