promptAction.openToast({ message: 'hdslistitem' });
}
})
}
}
.width('100%')
.height('100%')
.margin(10)
}.backgroundColor(0x1a0a59f7).height('100%')
}
}

从5.1.1 (19)版本开始，新增支持资源注册。 适用于需要快速定制应用内 Symbol图标 ，不想强依赖于系统版本中预制的系统Symbol图标资源。 资源注册支持Phone、Tablet、PC/2in1设备。 将Symbol图标资源（TTF文件，设计规范参见 图标设计文档 ）与动效参数资源（JSON文件）放入entry/src/main/resources/rawfile目录下，可在此目录下新建子目录。 多语言场景，在entry/src/main/resources目录中对应语言目录下的string.json文件中配置对应的Symbol图标Unicode值。 {
"string": [
{
"name": "symbol_custom_phone_fill_1",
"value": "0x100016"
}
]
} 多语言场景，在entry/src/main/resources目录中对应语言目录下的string.json文件中配置对应的Symbol图标Unicode值。 导入相关模块。 import { symbolRegister } from '@kit.UIDesignKit'
import { BusinessError } from '@kit.BasicServicesKit' 在通过SymbolGlyph/SymbolSpan组件展示自定义Symbol图标前，需要注册加载图标资源与动效参数资源。在需要展示自定义Symbol图标的页面通过SymbolGlyph/SymbolSpan组件展示该图标。 @Entry
@Component
struct Index {
aboutToAppear(): void {
try {
let result = symbolRegister.registerSymbol($rawfile("symbol/symbol_register.ttf"), $rawfile("symbol/symbol_register.json"));
} catch (error) {
let err = error as BusinessError;
console.error("errCode: " + err.code)
console.error("error: " + err.message);
}
}
build() {
Column(){
SymbolGlyph($r('app.string.symbol_custom_phone_fill_1'))
}
.width('100%')
.height('100%')
}
}

