以AES和SM4为例，随机生成对称密钥（SymKey），并获得二进制数据。 对称密钥对象可用于后续加解密操作，二进制数据可用于存储或传输。 对应的算法规格请查看 对称密钥生成和转换规格：AES 。 调用 cryptoFramework.createSymKeyGenerator ，指定字符串参数'AES256'，创建密钥算法为AES、密钥长度为256位的对称密钥生成器（SymKeyGenerator）。 调用 SymKeyGenerator.generateSymKey ，随机生成对称密钥对象（SymKey）。 调用 SymKey.getEncoded ，获取密钥对象的二进制数据。 以使用Promise方式随机生成AES密钥为例： import { cryptoFramework } from '@kit.CryptoArchitectureKit';

function testGenerateAesKey() {
// 创建SymKeyGenerator实例
let symKeyGenerator = cryptoFramework.createSymKeyGenerator('AES256');
// 使用密钥生成器随机生成对称密钥
let promiseSymKey = symKeyGenerator.generateSymKey();
promiseSymKey.then(key => {
// 获取对称密钥的二进制数据，输出256位密钥。长度为32字节
let encodedKey = key.getEncoded();
console.info('key hex: ' + encodedKey.data);
});
} 以使用Promise方式随机生成AES密钥为例： 同步方法（调用方法 generateSymKeySync ）： import { cryptoFramework } from '@kit.CryptoArchitectureKit';

function testSyncGenerateAesKey() {
// 创建SymKeyGenerator实例
let symKeyGenerator = cryptoFramework.createSymKeyGenerator('AES256');
// 使用密钥生成器随机生成对称密钥
let promiseSymKey = symKeyGenerator.generateSymKeySync();
// 获取对称密钥的二进制数据，输出256位密钥。长度为32字节
let encodedKey = promiseSymKey.getEncoded();
console.info('key hex: ' + encodedKey.data);
}

