以RSA和SM2为例，随机生成非对称密钥对（KeyPair），并获得二进制数据。 非对称密钥对可用于后续加解密等操作，二进制数据可用于存储或传输。 对应的算法规格请查看 非对称密钥生成和转换规格：RSA 。 调用 cryptoFramework.createAsyKeyGenerator ，指定字符串参数'RSA1024|PRIMES_2'，创建RSA密钥类型为RSA1024、素数个数为2的非对称密钥生成器（AsyKeyGenerator）。 调用 AsyKeyGenerator.generateKeyPair ，随机生成非对称密钥对象（KeyPair）。 KeyPair对象中包括公钥PubKey、私钥PriKey。 调用 AsyKeyGenerator.generateKeyPair ，随机生成非对称密钥对象（KeyPair）。 KeyPair对象中包括公钥PubKey、私钥PriKey。 调用 PubKey.getEncoded 和 PriKey.getEncoded ，分别获取密钥对象的二进制数据。 以使用Promise方式随机生成RSA密钥对为例： import { cryptoFramework } from '@kit.CryptoArchitectureKit';

function generateAsyKey() {
// 创建一个AsyKeyGenerator实例
let rsaGenerator = cryptoFramework.createAsyKeyGenerator('RSA1024|PRIMES_2');
// 使用密钥生成器随机生成非对称密钥对
let keyGenPromise = rsaGenerator.generateKeyPair();
keyGenPromise.then(keyPair => {
let pubKey = keyPair.pubKey;
let priKey = keyPair.priKey;
// 获取非对称密钥对的二进制数据
let pkBlob = pubKey.getEncoded();
let skBlob = priKey.getEncoded();
console.info('pk bin data: ' + pkBlob.data);
console.info('sk bin data: ' + skBlob.data);
});
}

