} catch (error) {
console.error(`Failed to scan bundle files

打开文件功能为安全防护类应用提供专用接口以获取文件描述符（fd）。 当安全防护类应用（如病毒扫描、恶意软件检测等）需要对设备上的文件进行安全扫描时，可能会遇到目标文件位于应用沙箱外且应用没有直接读取权限的情况。此时，可通过文件打开接口获取目标文件的文件描述符（fd），使安全防护应用能够正常访问和扫描这些文件，确保设备整体安全性。 导入模块。 // 导入企业威胁防护能力模块和文件IO模块
import { virusRemediation } from '@kit.EnterpriseThreatProtectionKit';
import { fileIo } from '@kit.CoreFileKit'; 通过调用接口 openFile ，获取目标文件的文件描述符（fd）。path参数为目标文件的绝对路径。使用完fd后应记得关闭。 import { BusinessError } from '@kit.BasicServicesKit';

// 获取文件fd，查看打印结果
function openFilePromise() {
// 目标文件路径，此处为示例路径，实际使用时需替换为用户指定的真实路径或通过参数传入
let targetFilePath: string = '/example/path/to/file.txt';
virusRemediation.openFile(targetFilePath).then((fd: number) => {
console.info(`Succeeded in opening file. Path: ${targetFilePath}, FD: ${fd}.`);
// 使用完fd后应记得关闭
fileIo.closeSync(fd);
}).catch((err: BusinessError) => {
// 根据错误码进行不同的业务处理
if (err.code === 1023803001) {
console.error('Access denied, please check if the file belongs to current user.');
} else {
console.error(`Failed to open file. Code: ${err.code}, message: ${err.message}.`);
}
});
}

文件隔离是指将检测到的威胁文件转移到安全隔离区。 在安全防护类应用检测到病毒、木马等恶意文件后可以使用文件隔离接口将恶意文件转移到安全隔离区，实现安全防护类应用对恶意文件的隔离能力。 导入模块。 import { virusRemediation } from '@kit.EnterpriseThreatProtectionKit'; 通过调用接口 isolateThreatFile ，实现对恶意文件的安全隔离。path参数为目标文件的绝对路径。 import { BusinessError } from '@kit.BasicServicesKit';

// 隔离文件，打印被隔离文件对应的隔离id
function isolateFilePromise() {
// 恶意文件路径，此处为示例路径，实际使用时需替换为真实文件路径
let maliciousFilePath: string = '/data/service/el2/test/test.txt';
virusRemediation.isolateThreatFile(maliciousFilePath).then((id: string) => {
console.info(`Succeeded in isolating file. Path: ${maliciousFilePath}, ID: ${id}.`);
}).catch((err: BusinessError) => {
// 根据错误码进行不同的业务处理
if (err.code === 1023804001) {
console.error('Invalid file type, only single files are supported.');
} else if (err.code === 1023804002) {
console.error('Application bundle path detected, please uninstall the app or disable running.');
} else {
console.error(`Failed to isolate file. Code: ${err.code}, message: ${err.message}.`);
}
});
}

文件隔离恢复是指将指定隔离ID的文件从隔离区还原至其原始存储路径。 当安全防护类应用之前扫描过程中将正常文件误判为威胁文件并已隔离时，可通过文件隔离恢复接口将已隔离的文件还原至原路径，从而确保正常业务文件可用，保障用户数据完整性与业务连续性。 导入模块。 import { virusRemediation } from '@kit.EnterpriseThreatProtectionKit'; 调用接口 restoreIsolatedFile ，实现对指定隔离ID的文件恢复并获取恢复路径。id参数为隔离文件的唯一标识符，可通过调用 queryIsolatedFiles 接口获取。 import { BusinessError } from '@kit.BasicServicesKit';

// 按指定隔离文件ID进行恢复，打印恢复后的文件路径
function restoreFilePromise() {
// 隔离文件ID，可通过queryIsolatedFiles()接口获取
let isolatedFileId: string = 'example-id-12345';
// 调用接口恢复指定ID的隔离文件
virusRemediation.restoreIsolatedFile(isolatedFileId).then((path: string) => {
console.info(`Succeeded in restoring file. Restore path: ${path}, ID: ${isolatedFileId}.`);
}).catch((err: BusinessError) => {
// 根据错误码进行不同的业务处理
if (err.code === 1023802001) {
console.error('Target file does not exist, please verify the file path.');
} else if (err.code === 1023802002) {
console.error('Path access denied, please check path permissions.');
} else if (err.code === 1023802003) {
console.error('File name conflict, please rename or delete the existing file.');
} else {
console.error(`Failed to restore file. Code: ${err.code}, message: ${err.message}.`);
}
});
}

隔离区 ：是指系统中临时存放被识别为威胁的文件的区域。 文件隔离删除是指将隔离区的文件永久删除。 当隔离区的文件日益增加，磁盘空间占用持续增长时，可通过调用隔离文件删除接口，对已隔离文件进行删除，保证系统资源的高效利用并持续维护防护性能。 导入模块。 import { virusRemediation } from '@kit.EnterpriseThreatProtectionKit'; 通过调用接口 removeIsolatedFile ，实现对指定隔离ID文件的删除。id参数为隔离文件的唯一标识符，可通过调用 queryIsolatedFiles 接口获取。 import { BusinessError } from '@kit.BasicServicesKit';

// 对指定隔离文件ID进行删除
function removeIsolatedFilePromise() {
// 隔离文件ID，可通过queryIsolatedFiles()接口获取
let isolatedFileId: string = 'example-id-12345';
virusRemediation.removeIsolatedFile(isolatedFileId).then(() => {
console.info('Succeeded in removing isolated file.');
}).catch((err: BusinessError) => {
// 根据错误码进行不同的业务处理
if (err.code === 1023806001) {
console.error('Database error, please retry or contact support.');
} else if (err.code === 1023804003) {
console.error('Invalid isolation ID, please verify the ID exists.');
} else {
console.error(`Failed to remove isolated file. Code: ${err.code}, message: ${err.message}.`);
}
});
}

隔离查询功能帮助安全防护类应用获取当前用户下由该应用隔离的处于隔离状态的文件信息列表。 当安全防护类应用更新或卸载，导致原本存储在应用数据库中的隔离信息丢失时，可通过隔离查询接口，为安全防护类应用提供隔离信息查询的能力，快速获取自身应用已隔离的当前用户的文件信息，保障隔离恢复和隔离删除的可操作性。 导入模块。 import { virusRemediation } from '@kit.EnterpriseThreatProtectionKit'; 通过声明查询结果回调queryCallback，并调用 queryIsolatedFiles 接口，获取已隔离文件的文件信息。 function startQueryTask() {
// 查询隔离文件信息回调
let onQuery: (files: virusRemediation.IsolatedFileInfo[]) => void = (files: virusRemediation.IsolatedFileInfo[]) => {
files.forEach((value: virusRemediation.IsolatedFileInfo, index: number) => {
console.info(`Succeeded in getting isolated file, file id: ${value.id}.`);
})
};
// 查询隔离文件信息结束通知
let onComplete: () => void = () => {
console.info(`Query completed`);
};
// 查询隔离文件信息错误报告
let onError: (code: number, message: string) => void = (code: number, message: string) => {
console.error(`Query error, error code: ${code}, message: ${message}`);
}
let queryCallback: virusRemediation.QueryCallback = {
onQuery: onQuery,
onComplete: onComplete,
onError: onError
};
try {
virusRemediation.queryIsolatedFiles(queryCallback);
} catch (error) {
console.error(`Failed to get isolated file. Error: ${error}`);
}
}

从26.0.0版本开始，新增提供威胁进程终止接口，为企业安全类应用提供对运行中恶意进程及可疑进程的安全处置能力。 威胁进程终止是一种主动防御手段，通过对已识别为恶意或存在安全风险的进程执行终止操作，使威胁失去运行载体，从而达到遏制攻击、保护终端安全的目的。该能力主要服务于企业级安全厂商，帮助其安全产品在客户端环境中实现自动化或可控的威胁清除。 支持三方杀软对规格范围内的威胁进程执行终止操作。典型应用场景包括：实时防护发现威胁后的即时阻断、违规软件或违规行为的强制终止、以及应急响应事件中的快速威胁遏制。 导入模块。 import { virusRemediation } from '@kit.EnterpriseThreatProtectionKit'; 调用接口 terminateProcess ，实现终止指定PID的威胁进程。 function terminateProcessPromise() {
let pid: number = 0;
virusRemediation.terminateProcess(pid).then(() => {
console.info(`Succeeded in terminating process.`);
}).catch((err: BusinessError) => {
if (err.code === 1023807001) {
console.error('Process not found.');
} else if (err.code === 1023807002) {
console.error('Access and disposal are denied for this process.');
} else if (err.code === 1023807003) {
console.error(`Access to other users' processes is not allowed.`);
} else {
console.error(`Failed to terminate process. Code: ${err.code}, message: ${err.message}.`);
}
});
}

开通FIDO免密身份认证功能，使用用户已有的生物特征开通FIDO免密身份认证能力。 使用FIDO免密身份认证功能，使用用户已开通的生物特征进行FIDO免密身份认证。 关闭FIDO免密身份认证功能，使用用户已开通的生物特征注销FIDO免密身份认证能力。 获取生物识别权限：ohos.permission.ACCESS_BIOMETRIC。 移动端设备需要支持生物特征（指纹/3D人脸），查询当前移动端设备是否支持ATL4级别的认证可信等级。 import { BusinessError } from '@kit.BasicServicesKit';
import { userAuth } from '@kit.UserAuthenticationKit';
// ...
function getAvailableStatus(){
try {
// 示例，查询设备人脸识别是否支持ATL4级别的认证可信等级
userAuth.getAvailableStatus(userAuth.UserAuthType.FACE, userAuth.AuthTrustLevel.ATL4);
console.info('current auth trust level is supported');
} catch (error) {
const err: BusinessError = error as BusinessError;
console.error(`current auth trust level is not supported. Code is ${err?.code}, message is ${err?.message}`);
}
} 移动端设备需要支持生物特征（指纹/3D人脸），查询当前移动端设备是否支持ATL4级别的认证可信等级。 FIDO服务需要联网，以便提供完整的在线身份校验服务。应用在调用本服务API前，需将FIDO服务联网行为向用户明示，并且取得用户同意。 FIDO服务会将匿名化的指纹ID和面容ID等个人信息返回至三方应用，以提供绑定具体生物特征的免密认证能力。应用将个人信息上云前，需要向用户明示并且取得同意，详细请参考 个人数据处理说明 。

