从6.1.1(24)开始支持获取星闪合作设备集合信息。 合作设备集合是由多个成员设备协同提供特定服务的整体，例如一副星闪耳机包含左右两个耳机单元。当配对的外设属于某个合作设备集合时，通过 getPairedDevices 接口仅能获取该集合中首个配对的成员设备，无法直接获取其他成员设备信息。作为集合使用者，可通过主动查询或订阅通知的方式，获取该合作设备集合内所有成员设备的完整信息。 更多技术细节可参考 星闪标准 《星闪无线通信系统 基础应用层 合作设备集合管理》。 提供获取合作设备集合信息的方式，主动查询和订阅信息变化。 导入相关模块。 import { hilog } from '@kit.PerformanceAnalysisKit';
import { BusinessError } from '@kit.BasicServicesKit';
import { cdsm, manager, remoteDevice } from '@kit.NearLinkKit'; 创建合作设备集合客户端实例，参数addr是通过 getPairedDevices 获取的设备地址，并且此设备是合作设备集合的成员设备。 @State deviceAddress: string = '00:11:22:33:AA:FF';
cdsmClient: cdsm.CdsmClient | null = null;
// ...
try {
this.cdsmClient = cdsm.createCdsmClient(this.deviceAddress);
hilog.info(this.domainId, this.logTag, `Create CDSM client: ${JSON.stringify(this.cdsmClient)}`);
// ...
} catch (err) {
hilog.error(this.domainId, this.logTag,
`errCode: ${(err as BusinessError).code}, errMessage: ${(err as BusinessError).message}`);
}

