{
NetworkBoost_HandoverMode mode = NB_MODE_DISCRETION;
int32_t ret = HMS_NetworkBoost_SetHandoverMode(mode);
printf("设置连接迁移模式结果: %d\n", ret);
return ret;
} 调用SetHandoverMode接口，设置为自主模式，禁止系统发起连接迁移。

