});
session1.cancel(request1); // 取消request1请求

从6.0.0(20)开始，支持HTTP缓存。 HTTP缓存是一种在客户端存储网络资源副本的机制，当后续请求相同资源时，可直接从缓存中获取，无需再次向服务器发起完整请求。HTTP缓存适用于静态资源（如图片、CSS）和高访问量内容，能有效提升网络资源获取性能。Remote Communication Kit模块提供HTTP缓存功能，遵循 RFC 9111 协议，支持独立配置缓存策略与持久化存储路径，实现内存、磁盘双重缓存管理，并提供自定义缓存拦截器能力。 HTTP缓存基本功能能力支持Phone、2in1、Tablet、Wearable、TV设备。 在需要频繁获取网络热点数据的场景下，网络请求耗时在总时长中占比较大。开发者可以通过创建 ResponseCache 实例，并将其配置到Session中，即可使用HTTP缓存功能，提升资源加载性能。 导入模块。 import { rcp } from '@kit.RemoteCommunicationKit'; 创建 ResponseCache 实例。其中，pathToFolder即HTTP缓存响应记录文件路径，'/path/dir'请根据实际情况替换为需要存储HTTP缓存的沙箱路径。 // 创建ResponseCache实例
const responseCache = new rcp.ResponseCache({
persistent: {
kind: 'file-system',
pathToFolder: '/data/storage/el2/base/entry/temp/BaseHttp' // 请根据自身业务选择合适的路径
}
}); 创建 ResponseCache 实例。其中，pathToFolder即HTTP缓存响应记录文件路径，'/path/dir'请根据实际情况替换为需要存储HTTP缓存的沙箱路径。 创建会话。在创建Session时，传入responseCache实例。 const session: rcp.Session = rcp.createSession({
requestConfiguration: {
cache: responseCache,
}
});

从6.0.0(20)开始，支持Session间缓存共享。 Session之间数据是隔离的，当业务场景需要实现跨Session访问缓存数据时，可通过以下两种标准方式达成目标： 引用相同的HTTP响应缓存实例，不同Session能直接访问同一缓存池中的数据； 配置相同的缓存存储路径，使各个Session基于同一存储位置读写缓存，以此实现缓存数据的跨Session共享与交互。 Session间缓存共享能力支持Phone、2in1、Tablet、Wearable、TV设备。 创建一个 ResponseCache 实例，将其配置到不同Session中，可以在Session间共享缓存数据。 导入模块。 import { rcp } from '@kit.RemoteCommunicationKit'; 创建 ResponseCache 实例。其中，pathToFolder即缓存记录文件路径，'/path/dir'请根据实际情况替换为想要存储HTTP缓存的沙箱路径。 // 创建ResponseCache实例
const responseCache = new rcp.ResponseCache({
persistent: {
kind: 'file-system',
pathToFolder: '/data/storage/el2/base/entry/temp/SomeInstance' // 请根据自身业务选择合适的路径
}
}); 创建 ResponseCache 实例。其中，pathToFolder即缓存记录文件路径，'/path/dir'请根据实际情况替换为想要存储HTTP缓存的沙箱路径。 创建SessionA和SessionB。配置responseCache实例到SessionA和SessionB中。 const sessionA: rcp.Session = rcp.createSession({
requestConfiguration: {
cache: responseCache,
}
});
const sessionB: rcp.Session = rcp.createSession({
requestConfiguration: {
cache: responseCache,
}
});

从6.0.0(20)开始，支持自定义缓存拦截器。 Remote Communication Kit模块提供了 拦截器 能力，支持开发者根据业务需求，实现自定义缓存拦截器。通过拦截器机制，开发者能够介入缓存处理流程，包括缓存数据的预处理、加载逻辑定制等，从而精准匹配复杂业务场景对缓存逻辑的差异化需求，提升系统的灵活性与可扩展性。 自定义缓存拦截器能力支持Phone、2in1、Tablet、Wearable、TV设备。 导入模块。 import { rcp } from '@kit.RemoteCommunicationKit'; 实现自定义缓存拦截器。 class BlindCacheInterceptor implements rcp.Interceptor {
private readonly cache: rcp.ResponseCache;
constructor(cache: rcp.ResponseCache) {
this.cache = cache;
}
async intercept(context: rcp.RequestContext, next: rcp.RequestHandler): Promise<rcp.Response> {
const key: rcp.ResponseCacheKey = {
url: context.request.url,
method: context.request.method,
};
const responseInCache = await this.cache.get(key);
if (responseInCache) {
return rcp.createResponse(context.request, responseInCache.response, new Date());
}
const networkResponse = await next.handle(context);
await this.cache.set(key, rcp.createCachedResponse(networkResponse));
return networkResponse;
}
}

从26.0.0版本开始，新增支持QUIC长连接能力。 QUIC长连接基于QUIC（Quick UDP Internet Connections）协议实现，相比传统的TCP协议，QUIC在速度、灵活性和稳定性方面更具备核心优势。QUIC长连接在即时通讯、实时推送、在线协作等场景中具有广泛应用，能够显著提升通信效率和用户体验。在远场通信服务的框架中，QUIC长连接通过 RCP_QUIC 提供支持，为开发者提供高效、可靠的端云通信能力。 在服务端主动推送消息的场景下，QUIC长连接通过无队头阻塞的多路复用及更少的握手次数，有效优化传统HTTP/1.1及HTTP/2协议中的队头阻塞与多次握手问题，降低网络延迟和资源消耗。此外，QUIC长连接能够保持连接的持久性，减少连接建立和断开频率，进一步提升通信效率。 在.cpp文件导入模块。 #include "RemoteCommunicationKit/rcp_quic.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h> 在CMakeLists.txt文件中添加以下lib依赖包（具体请见 C API开发准备 ）。 librcp_quic.so 在CMakeLists.txt文件中添加以下lib依赖包（具体请见 C API开发准备 ）。 自定义全局变量，可用于QUIC连接与流配置。 uint64_t g_StreamId = 0;
uint64_t userData = 0;
char *alpn = "h3";
const char *serverName = "www.example.com"; // 示例代码，仅用于展示调用，实际运行请替换为真实的QUIC协议服务端地址
uint64_t serverPort = 443; // 示例代码，仅用于展示调用，实际运行请替换为真实端口 自定义全局变量，可用于QUIC连接与流配置。 自定义回调方法，用于后续步骤注册监听事件，可在回调中补充需要的业务逻辑。 // 连接成功时触发
void OnConnectedImpl(Rcp_QuicConn *conn, void *userObject) {
(void)conn;
if (userObject == NULL) {
return;
}
}

// 异常发生时触发
void OnErrorImpl(Rcp_QuicConn *conn, void *userObject, Rcp_QuicErrorCode errCode, const char *errDetail) {
(void)conn;
if (errCode == 0 || userObject == NULL || errDetail == NULL) {
return;
}
}

