};
// 注册智慧出行连接状态的监听
awareness.on('smartMobilityStatus', types, callBack);
// ...
} catch (e) {
// 捕获接口调用异常时的错误码并做相应处理
hilog.error(0x0000, 'testTag', `on smart mobility status listener error, error code: ${e?.code}`);
}

开发者开发带UI界面的基础驱动，适用于各种复合设备，需要通过UI界面设置对应的独特驱动能力或者通过UI界面展示从设备侧获取的信息，例如带有侧键的鼠标，手写板，身份证读卡器等设备。 请参考 环境准备 完成开发前的准备工作。 扩展外设管理基本能力如下，更多详情请查阅 @ohos.driver.deviceManager 。 应用可通过查询绑定扩展外设，从而使用扩展外设的定制驱动能力。 开发示例如下（仅供参考）：为开发者提供的示例代码为同时开发客户端和服务端的Demo，并实现IPC通信。 创建新工程，请参考 创建一个新的工程 ，创建一个HarmonyOS工程。 开发驱动客户端，请选择Empty Ability模板。 开发驱动服务端，请选择Native C++模板。 同时开发驱动客户端和服务端，请选择Native C++模板。 创建新工程，请参考 创建一个新的工程 ，创建一个HarmonyOS工程。 开发驱动客户端，请选择Empty Ability模板。 开发驱动服务端，请选择Native C++模板。 同时开发驱动客户端和服务端，请选择Native C++模板。 在文件中导入相关Kit，并声明想要绑定的USB设备的productId、vendorId以及与驱动通信的Code。 以下示例代码均写在entry/src/main/ets/pages/Index.ets文件中。 import { hilog } from '@kit.PerformanceAnalysisKit';
import { deviceManager } from '@kit.DriverDevelopmentKit';
import { BusinessError } from '@kit.BasicServicesKit';
import { rpc } from '@kit.IPCKit';

const REQUEST_CODE: number = 99; // 自定义通信Code，此处仅供参考
const productId: number = 4258; // 请声明连接的USB设备的productId
const vendorId: number = 4817; // 请声明连接的USB设备的vendorId
const DOMAIN = 0x0000;

当应用需要获取当前设备状态时，可以调用Stationary模块，例如：需要判断当前设备处于绝对静止状态或者相对静止状态。 详细的接口介绍请参考 @ohos.stationary (设备状态感知框架) 。 目前只提供了算法框架，API接口测试框架的调用返回结果为:data={"type":3,"value":-1}; 如需相对静止和绝对静止能力，则具体算法需要开发者自己在device_status/libs/src/algorithm实现，可参考案例如下： 导入模块。 import { stationary } from '@kit.MultimodalAwarenessKit';
import { BusinessError } from '@kit.BasicServicesKit'; 订阅绝对静止的进入事件，1秒上报一次。 let reportLatencyNs = 1000000000; // 单位：纳秒
try {
stationary.on('still', stationary.ActivityEvent.ENTER, reportLatencyNs, (data) => {
console.info('data=' + JSON.stringify(data));
})
// ...
} catch (error) {
let message = (error as BusinessError).message;
console.error('stationary on failed:' + message);
} 查询绝对静止状态的进入事件。 try {
stationary.once('still', (data) => {
console.info('data=' + JSON.stringify(data));
})
// ...
} catch (error) {
let message = (error as BusinessError).message;
console.error('stationary once failed:' + message);
}

当应用需要获取用户动作时，可以调用motion模块，例如判断用户当前是用左手还是右手操作设备屏幕。 详细的接口介绍请参考 @ohos.multimodalAwareness.motion (动作感知能力) 。 从API version 15开始，支持获取操作手状态。从API version 20开始，支持获取握持手状态。 使用motion模块获取用户操作手时，需要权限：ohos.permission.ACTIVITY_MOTION 或 ohos.permission.DETECT_GESTURE，具体申请方式请参考 声明权限 。 此功能如果设备不支持，将返回801错误码。 能力有效范围：不包含距离屏幕边缘8mm内区域。 结果上报条件：首次订阅或切换操作手后，连续点数次触发。 触控响应说明：屏幕四周边缘8mm范围内不支持触控响应。 导入模块。 import { motion } from '@kit.MultimodalAwarenessKit';
import { BusinessError } from '@kit.BasicServicesKit'; 定义回调函数接收操作手结果 let callback:Callback<motion.OperatingHandStatus> = (data:motion.OperatingHandStatus) => {
console.info('callback succeeded' + data);
}; 订阅操作手感知 try {
motion.on('operatingHandChanged', callback);
console.info('on succeeded');
// ...
} catch (err) {
let error = err as BusinessError;
console.error('Failed on and err code is ' + error.code);
// ...
} 取消订阅操作手感知 try {
motion.off('operatingHandChanged');
console.info('off succeeded');
// ...
} catch (err) {
let error = err as BusinessError;
console.error('Failed off and err code is ' + error.code);
// ...
}

MetadataBinding（记忆链接）指由第三方应用提供 鸿蒙App Linking链接 ，系统将当前用户浏览的内容与鸿蒙App Linking链接进行关联并保存的功能。 详细的接口介绍请参考 @ohos.multimodalAwareness.metadataBinding (记忆链接) 。 第三方应用可使用记忆链接功能，将鸿蒙App Linking链接映射到调用接口的系统应用或服务。例如，用户在【电商应用】中浏览某个商品时，截图保存了该商品的图片，系统将记录图片与【电商应用】提供的鸿蒙App Linking链接的映射关系。当用户再次浏览该图片时，用户主动触发小艺识屏能力，系统会提醒用户是否需要返回【电商应用】查看商品详情，提醒样式由小艺配置。 本模块首批接口从API version 18开始支持。后续版本的新增接口，采用上角标单独标记接口的起始版本。 鸿蒙App Linking链接超过128字节时会编码失败，截图保存原始图像 导入模块。 import { metadataBinding } from '@kit.MultimodalAwarenessKit';
import { BusinessError } from '@kit.BasicServicesKit';
import { Callback } from '@kit.BasicServicesKit'; 定义记忆服务回调及包名, 函数接收回传编码的内容。 let callback : Callback<number> = (event: number) => {};
let bundleName: string = ''; 定义记忆服务回调及包名, 函数接收回传编码的内容。 订阅记忆服务。 try {
metadataBinding.on('operationSubmitMetadata', bundleName, callback);
console.info('on succeeded');
// ...
} catch (err) {
let error = err as BusinessError;
console.error('Register event error and err code is ' + error.code);
// ...
}

接入手写套件后，可以在应用中创建手写功能界面。界面包括画布和工具栏两部分，画布部分支持手写笔和手指的书写效果绘制，工具栏部分提供多种笔刷和编辑工具，并支持对手写功能进行设置。接入手写套件后将自动开启一笔成形和报点预测功能，无需再单独接入。 从5.1.0(18)开始，手写套件新增支持设置工具栏默认笔刷、各笔刷默认宽度。 从6.0.0(20)开始，手写套件新增支持自定义画布大小、缩略图能力。 从6.1.0(23)开始，手写套件新增禁用画布缩放、设置滚动位置ScrollTo及监听长画布滚动位置、自定义长画布最大高度能力。 从26.0.0开始，手写套件新增手写波轮菜单、预置图形工具、矩形套索，以及新增自定义手写工具能力。 Pen Kit手写套件仅支持上下滑动，不支持左右滑动。 EntryAbility入口设置Context。 import { UIAbility } from '@kit.AbilityKit';
import { window } from '@kit.ArkUI';
import GlobalContext from '../utils/ContextConfig';

export default class EntryAbility extends UIAbility {

onWindowStageCreate(windowStage: window.WindowStage): void {
// 主窗口已创建，为此功能设置主页面
windowStage.loadContent('pages/HandWritingDemo', (err) => {
if (err.code) {
return;
}
});
GlobalContext.setContext(this.context);
}
} EntryAbility入口设置Context。 新建GlobalContext类。 import { common } from '@kit.AbilityKit';

declare namespace globalThis {
let _brushEngineContext: common.UIAbilityContext;
};

export default class GlobalContext {

static getContext(): common.UIAbilityContext {
return globalThis._brushEngineContext;
}

static setContext(context: common.UIAbilityContext): void {
globalThis._brushEngineContext = context;
}
}

