OH_AudioSuiteEngine_Create(&g_audioSuiteEngine);

// 创建实时播放空间渲染的管线。
OH_AudioSuiteEngine_CreatePipeline(g_audioSuiteEngine, &g_audioSuitePipeline,
OH_AudioSuite_PipelineWorkMode::AUDIOSUITE_PIPELINE_REALTIME_MODE);

