import { photoAccessHelper } from '@kit.MediaLibraryKit'; 导入依赖，需要导入相机框架、媒体库、图片相关领域依赖。 确定拍照输出流。 通过 CameraOutputCapability 中的photoProfiles属性，可获取当前设备支持的拍照输出流，通过 createPhotoOutput 方法创建拍照输出流。 function getPhotoOutput(cameraManager: camera.CameraManager,
