private photoOutput: camera.PhotoOutput | undefined = undefined;
private session: camera.PhotoSession | camera.VideoSession | undefined = undefined;

// 初始化相机。
async initCamera(context: Context, surfaceId: string): Promise<void> {
console.info(`initCamera surfaceId: ${surfaceId}`);
try {
await this.releaseCamera();
// 获取相机管理器实例。
this.cameraManager = camera.getCameraMa

从API version 20开始，支持设置白平衡效果。白平衡是相机的色彩校正技术，通过设置白平衡，使照片产生不同的效果。目前白平衡效果支持：拍照（ PhotoSession ）、录像（ VideoSession ）和安全相机模式（ SecureSession ）。 详细的API说明请参考 Camera 。 导入camera接口，接口中提供相机相关的属性和方法。 import { camera } from '@kit.CameraKit';
import { BusinessError } from '@kit.BasicServicesKit'; 导入camera接口，接口中提供相机相关的属性和方法。 白平衡的设置提供两种方法。 方法一：通过 isWhiteBalanceModeSupported 判断是否支持该白平衡模式。再通过 setWhiteBalanceMode 和 getWhiteBalanceMode 分别设置和查看白平衡模式（只能查看当前已设置的白平衡模式）。该接口提供白平衡模式设置，目前包括：自动，手动，阴天、白炽光、荧光和日光。当同时设置白平衡模式和设置白平衡值时，仅可生效一种，默认白平衡模式优先生效。 function isWhiteBalanceModeSupported(session: camera.PhotoSession | camera.VideoSession): boolean {
let status: boolean = false;
let whiteBalanceMode: camera.WhiteBalanceMode | undefined = undefined;
try {
let mode: camera.WhiteBalanceMode = camera.WhiteBalanceMode.DAYLIGHT;
status = session.isWhiteBalanceModeSupported(mode);
if(status){
session.setWhiteBalanceMode(mode);
}
whiteBalanceMode = session.getWhiteBalanceMode();
} catch (error) {
let err = error as BusinessError;
console.error(`The isWhiteBalanceModeSupported call failed. error code: ${err.code}`);
}
return status;
} 方法二：通过 getWhiteBalanceRange 接口，获取当前设备支持的白平衡值范围。再通过 setWhiteBalance 和 getWhiteBalance 分别设置和查看白平

从API version 20开始，相机框架通过相机控制器，为应用在直播场景提供美颜、虚化等能力。 相机控制器为直播和视频通话场景设计，目前仅支持在前置镜头的录像模式下使用，最高可支持1080P分辨率和30fps帧率。 详细的API说明请参考 Camera 。 导入camera接口，接口中提供了相机相关的属性和方法，导入方法如下。 import { camera } from '@kit.CameraKit';
import { BusinessError } from '@kit.BasicServicesKit'; 导入camera接口，接口中提供了相机相关的属性和方法，导入方法如下。 通过 isControlCenterSupported 接口，查询当前设备及当前场景是否支持相机控制器。 function isControlCenterSupported(videoSession: camera.VideoSession): boolean {
let isSupported: boolean = videoSession.isControlCenterSupported();
return isSupported;
} 通过 isControlCenterSupported 接口，查询当前设备及当前场景是否支持相机控制器。 通过 getSupportedEffectTypes 接口，查询当前设备及当前场景下，相机控制器支持的效果类型。 function getSupportedEffectTypes(videoSession: camera.VideoSession): Array<camera.ControlCenterEffectType> {
let effectTypes: Array<camera.ControlCenterEffectType> = [];
effectTypes = videoSession.getSupportedEffectTypes();
return effectTypes;
} 通过 getSupportedEffectTypes 接口，查询当前设备及当前场景下，相机控制器支持的效果类型。

从API version 19开始，支持设置微距能力。微距能力是指通过光学设计与算法优化，实现近距离对焦并清晰捕捉微小物体细节的相机功能。 详细的API说明请参考 Camera 。 导入camera接口，接口中提供了相机相关的属性和方法，导入方法如下。 import { camera } from '@kit.CameraKit';
import { BusinessError } from '@kit.BasicServicesKit'; 导入camera接口，接口中提供了相机相关的属性和方法，导入方法如下。 通过 isMacroSupported 接口，查询当前设备是否支持微距能力。 let isSupported: boolean = photoSession.isMacroSupported(); 通过 isMacroSupported 接口，查询当前设备是否支持微距能力。 通过 enableMacro 接口，开启或关闭微距能力。 function EnableMacro(photoSession: camera.PhotoSession): void {
let isSupported: boolean = photoSession.isMacroSupported();
if (isSupported) {
photoSession.enableMacro(true);
}
} 通过 enableMacro 接口，开启或关闭微距能力。 从API version 20开始，支持监听微距能力是否发生改变。 注册macroStatusChanged事件监听微距能力变化，事件监听可参考 on('macroStatusChanged') 。

从API version 18开始支持多摄同开，即应用同时开启前置/后置相机进行预览和录像（前置/后置相机同时拍照功能待开放）。 由于多摄同开需要前置/后置相机同时运行，所以对于相机功能有较大限制。当前版本仅支持以下七项基础功能，请勿对多摄同开开启的相机进行超出以下七种基础功能范围之外的查询、设置和使能。 详细的API说明请参考 Camera 。 Context获取方式请参考： 获取UIAbility的上下文信息 。 需要导入相机框架、媒体库、图片等相关领域依赖。 import { photoAccessHelper } from '@kit.MediaLibraryKit';
import { camera } from '@kit.CameraKit';
import { media } from '@kit.MediaKit';
import { fileIo } from '@kit.CoreFileKit';
import { common } from '@kit.AbilityKit';
import { BusinessError } from '@kit.BasicServicesKit'; 需要导入相机框架、媒体库、图片等相关领域依赖。 通过 getCameraDevice 获取对应的前置和后置相机。如果接口返回undefined，基于示例中的配置信息，表示当前设备不支持指定位置（前置/后置）的默认类型相机，无法实现多摄同开功能。 function getSupportedCamerasFn(cameraManager: camera.CameraManager)
{
let cameras = cameraManager.getSupportedCameras();

// 如果相机数量少于2，说明只存在单侧相机，返回。
if (cameras.length < 2) {
return;
}

// 获取逻辑后置和逻辑前置。
let curCameraDeviceBack = cameraManager.getCameraDevice(camera.CameraPosition.CAMERA_POSITION_BACK, camera.CameraType.CAMERA_TYPE_DEFAULT);
let curCameraDeviceFront = cameraManager.getCameraDevice(camera.CameraPosition.CAMERA_POSITION_FRONT, camera.CameraType.CAMERA_TYPE_DEFAULT);
}

从API version 23开始，相机框架提供YUV格式图片拍照能力。与普通拍照相比，YUV拍照获取到的是未经过编码的图像数据，完整保留了传感器捕获的原始亮度和色度信息，适用于视频编码或专业处理。同时，拍摄过程会产生更高的能耗开销，保存会占用更多的存储空间。 详细的相机功能API说明请参考Camera模块描述 OH_Camera 。 导入依赖模块。 获取拍照输出的数据需要用到系统提供的image、dataSharePredicates、photoAccessHelper接口能力，方法如下。 import { BusinessError } from '@kit.BasicServicesKit';
import { camera } from '@kit.CameraKit';
import { dataSharePredicates } from '@kit.ArkData';
import { fileIo } from '@kit.CoreFileKit';
import { image } from '@kit.ImageKit';
import { photoAccessHelper} from '@kit.MediaLibraryKit'; 获取拍照输出的数据需要用到系统提供的image、dataSharePredicates、photoAccessHelper接口能力，方法如下。 获取相机设备完整输出能力。 通过 getSupportedFullOutputCapability 方法，获取当前相机设备支持的所有输出流的能力，包含预览流、拍照流、录像流等。输出流在 CameraOutputCapability 中的各个profile字段中，其中拍照流支持YUV格式。 function getFullOutputCapability(cameraManager: camera.CameraManager, cameraDevice: camera.CameraDevice, sceneMode: camera.SceneMode): camera.CameraOutputCapability | undefined {
let cameraOutputCapability = cameraManager.getSupportedFullOutputCapability(cameraDevice, sceneMode);
if (!cameraOutputCapability) {
console.error("cameraManager.getSupportedFullOutputCapability error");
return undefined;
}
return cameraOutputCapability;
}

相机框架提供对设备对焦的能力，业务应用可以根据使用场景进行对焦模式和对焦点的设置。 详细的API说明请参考 Camera API参考 。 导入相关接口，导入方法如下。 import { camera } from '@kit.CameraKit';
