#include "ohcamera/capture_session.h"
#include "ohcamera/photo_output.h"
#include "ohcamera/preview_output.h"
#include "ohcamera/video_output.h"
#include "ohcamera/camera_manager.h"

开发者可以调用DRM Kit的C/C++接口实现DRM证书管理、DRM许可证管理、DRM节目授权、DRM节目解密等数字版权保护功能。 DRM Kit提供MediaKeySystem实现DRM证书管理、DRM许可证管理功能，并管理MediaKeySession实例；MediaKeySession实现DRM节目授权，并可支持Media Kit或AVCodec Kit实现DRM节目解密以实现DRM节目播放。 导入DRM Kit接口。 #include "multimedia/drm_framework/native_drm_common.h"
#include "multimedia/drm_framework/native_drm_err.h"
#include "multimedia/drm_framework/native_mediakeysession.h"
#include "multimedia/drm_framework/native_mediakeysystem.h" 在CMake脚本中链接动态库。 target_link_libraries(PUBLIC libnative_drm.so) 获取设备支持的DRM解决方案名称和唯一标识的列表。 uint32_t count = 3; // count是当前设备实际支持的DRM插件的个数，用户根据实际情况设置。
DRM_MediaKeySystemDescription descriptions[3];
memset(descriptions, 0, sizeof(descriptions));
Drm_ErrCode ret = OH_MediaKeySystem_GetMediaKeySystems(descriptions, &count);
if (ret != DRM_ERR_OK) {
