import { BusinessError } from '@kit.BasicServicesKit';
import { common } from '@kit.AbilityKit';
import { fileIo } from '@kit.CoreFileKit';
import { resourceManager } from '@kit.LocalizationKit'; 全局导入Image模块，根据实际需求导入对应的Kit模块。 获取图片。 方法一：通过沙箱路径直接获取，此方法 仅适用 于应用沙箱中的图片。获取方式请参考 获取应用文件路径 。 function getFilePath(context: Context, fileName: string): string {
const filePath: string = context.cacheDir + '/' + fileName;
return filePath;
} 方法二：通过沙箱路径获取图片的文件描述符。具体请参考 @ohos.file.fs (文件管理) 文档。该方法需要导入@kit.CoreFileKit模块。 function getFileFd(context: Context, fileName: string): number | undefined {
try {
const filePath: string = context.cacheDir + '/' + fileName;
const file: fileIo.File = fileIo.openSync(filePath, fileIo.OpenMode.READ_ONLY);
const fd: number = file?.fd;
return fd;
} catch (err) {
console.error(`Failed to get the fileFd with error: ${err}.`);
return undefined;
}
} 方法三：通过资源管理

图片编码指将PixelMap压缩成不同格式的图片文件，用于保存和传输。 支持使用 PackToData 和 PackToFile 将 PixelMap 编码为JPEG、WebP、PNG、HEIC和TIFF格式。 从API version 18开始，支持使用 PackToDataFromPixelmapSequence 和 PackToFileFromPixelmapSequence 将多个PixelMap编码为GIF格式。 从API版本26.0.0开始，支持使用 PackBinaryImageToTiffFile 和 PackBinaryImageToTiffData 将二值图像数据编码为TIFF格式。 图片编码相关API的详细介绍请参见 ImagePacker 。 导入相关模块包。 // 导入相关模块。
