{
napi_value result = nullptr;
napi_get_undefined(env, &result);

napi_value thisVar = nullptr;
napi_value argValue[1] = {0};
size_t argCount = 1;

napi_get_cb_info(env, info, &argCount, argValue, &thisVar, nullptr);

