for (let j = 0; j < fontConfig.fallback

自定义字体是指开发者根据应用需求创建或选择的字体，通常用于实现特定的文字风格或满足独特的设计要求。当应用需要使用特定的文本样式和字符集时，可以注册并使用自定义字体进行文本渲染。 自定义字体的注册 是指将字体文件（如ttf、otf文件等）从应用资源注册到系统中，使得应用能够使用这些字体进行文本渲染。注册过程通常指将字体文件通过字体管理接口注册到系统字体库中，以便在应用中进行调用。 自定义字体的使用 是指在应用中显式指定使用已注册的自定义字体进行文本绘制。开发者可以根据需要选择特定的文本样式（如常规、粗体、斜体等），并将其应用到UI元素、文本控件或其他文本展示区域，以确保符合设计要求并提供一致的视觉效果。 注册使用自定义字体的相关接口如下所示，详细接口说明请参考 Drawing 。 在工程的src/main/cpp/CMakeLists.txt文件中添加以下lib。 libnative_drawing.so 在工程的src/main/cpp/CMakeLists.txt文件中添加以下lib。 导入依赖的相关头文件。 #include <native_drawing/drawing_font_collection.h>
#include <native_drawing/drawing_text_typography.h>
#include <native_drawing/drawing_register_font.h> 创建字体管理器，建议优先使用OH_Drawing_CreateSharedFontCollection()创建可共享的字体集对象。 使用OH_Drawing_CreateFontCollection()和OH_Drawing_CreateSharedFontCollection()均可创建字体管理器OH_Drawing_FontCollection对象，但前者创建的字体集指针对象只能被一个段落生成器OH_Drawing_TypographyCreate对象使用，无法被多个段落生成器OH_Drawing_TypographyCreate对象共享使用。如需在多个段落生成器OH_Drawing_TypographyCreate对象间共享使用，请使用后者创建可共享的字体集对象。 OH_Drawing_FontCollection *fontCollection = OH_Drawing_CreateSharedFontCollection();

系统字体是指操作系统预设的字体，用于在没有指定自定义字体时显示文本，确保文本的可读性和一致性。默认的系统字体为“HarmonyOS Sans”。 使用系统字体 的情况通常是在应用未注册自定义字体，或在没有显式指定文本样式时，系统会使用默认的系统字体。另外，系统字体有多种，开发者可以先获取系统字体的配置信息，并根据信息中的字体家族名来进行系统字体的切换和使用。 禁用系统字体 的情况通常发生在开发者希望确保应用中仅使用自定义字体，而不受操作系统默认字体影响的场景。当自定义字体不存在时，不禁用系统字体，系统则会自动回退到默认字体。通过禁用系统字体，开发者可以在任何场景避免字体回退为系统默认字体，确保文本渲染符合设计预期，从而统一应用的视觉风格。 以下是系统字体相关的常用接口和结构体，详细接口说明请参考 Drawing 。 在工程的src/main/cpp/CMakeLists.txt文件中添加以下lib。 libnative_drawing.so 在工程的src/main/cpp/CMakeLists.txt文件中添加以下lib。 导入依赖的相关头文件。 #include <native_drawing/drawing_font_collection.h>
#include <native_drawing/drawing_text_typography.h>
#include <native_drawing/drawing_register_font.h>
#include <hilog/log.h> 获取系统字体的配置信息，可以通过返回的状态码确定获取信息是否成功，状态码包含的具体情况和对应含义可见 OH_Drawing_FontConfigInfoErrorCode 。 OH_Drawing_FontConfigInfoErrorCode fontConfigInfoErrorCode; // 用于接收错误代码
OH_Drawing_FontConfigInfo* fontConfigInfo = OH_Drawing_GetSystemFontConfigInfo(&fontConfigInfoErrorCode);
if(fontConfigInfoErrorCode != SUCCESS_FONT_CONFIG_INFO) {
OH_LOG_Print(LOG_APP, LOG_ERROR, LOG_DOMAIN, "PrintSysFontMetrics", "获取系统信息失败，错误代码为： %{public}d", fontConfigInfoErrorCode);
}

文本测量指的是在图形绘制中，对文本的尺寸和布局进行评估，计算文本在给定字体和样式下占用的空间（例如宽度、高度和其他相关信息）的过程。文本测量用于文本排版、布局、渲染以及调整文本显示的位置和大小等场景，便于更精准地控制与调整界面的布局和呈现，以达到设计预期。 文本宽度 ：测量给定文本在特定字体、大小和样式下的水平长度。 文本高度 ：测量给定文本的垂直高度，通常涉及文本的上升线、下降线等。 行间距 ：测量多行文本之间的垂直距离，通常与文本的行距相关。 字符间距 ：测量单个字符之间的水平距离，通常与字形和字体设计有关。 限制区域排版 ：在限定宽高区域内排版文本，获取实际排版尺寸和适配的字符串范围。 字符位置查询 ：根据屏幕坐标获取对应的字符位置，可用于文本选择、光标定位等交互场景。 字符和字形范围查询 ：在字形范围与字符范围之间进行相互转换，用于文本编辑、选择高亮等场景中字形与字符索引的映射。 文本测量中常用接口如下表所示，详细接口说明参考 @ohos.graphics.text (文本模块) 。 导入依赖的相关模块。 import { text, drawing } from '@kit.ArkGraphics2D'; 创建段落样式，并使用构造段落生成器ParagraphBuilder生成段落实例。 // 设置文本样式
let myTextStyle: text.TextStyle = {
color: {
alpha: 255,
red: 255,
green: 0,
blue: 0
},
fontSize: 100
};
// 创建一个段落样式对象，以设置排版风格
let myParagraphStyle: text.ParagraphStyle = {
textStyle: myTextStyle,
wordBreak: text.WordBreak.NORMAL
};
// 创建一个段落生成器
let paragraphBuilder = new text.ParagraphBuilder(myParagraphStyle, new text.FontCollection()); 创建段落样式，并使用构造段落生成器ParagraphBuilder生成段落实例。

文本测量指的是在图形绘制中，对文本的尺寸和布局进行评估，计算文本在给定字体和样式下占用的空间（例如宽度、高度和其他相关信息）的过程。文本测量用于文本排版、布局、渲染以及调整文本显示的位置和大小等场景，便于更精准地控制与调整界面的布局和呈现，以达到设计预期。 文本宽度 ：测量给定文本在特定字体、大小和样式下的水平长度。 文本高度 ：测量给定文本的垂直高度，通常涉及字体的上升线、下降线等。 行间距 ：测量多行文本之间的垂直距离，通常与字体的行距相关。 字符间距 ：测量单个字符之间的水平距离，通常与字形和字体设计有关。 限制区域排版 ：在限定宽高区域内排版文本，获取实际排版尺寸和适配的字符串范围。 字符位置查询 ：根据屏幕坐标获取对应的字符位置，可用于文本选择、光标定位等交互场景。 字符和字形范围查询 ：在字形范围与字符范围之间进行相互转换，用于文本编辑、选择高亮等场景中字形与字符索引的映射。 文本测量中常用接口如下表所示，详细接口说明参考 drawing_text_typography.h 。 在工程的src/main/cpp/CMakeLists.txt文件中添加以下lib。 libnative_drawing.so 在工程的src/main/cpp/CMakeLists.txt文件中添加以下lib。 导入依赖的相关头文件。 #include <native_drawing/drawing_font_collection.h>
#include <native_drawing/drawing_text_typography.h>
#include <native_drawing/drawing_text_declaration.h> 创建段落生成器ParagraphBuilder，并设置段落样式。 // 创建文本样式，设置文本颜色为黑色并设置字体大小为50
OH_Drawing_TextStyle *myTextStyle = OH_Drawing_CreateTextStyle();
OH_Drawing_SetTextStyleColor(myTextStyle, OH_Drawing_ColorSetArgb(0xFF, 0x00, 0x00, 0x00));
OH_Drawing_SetTextStyleFontSize(myTextStyle, 50.0);
// 创建一个段落样式对象，以设置排版风格
OH_Drawing_TypographyStyle *typographyStyle = OH_Drawing_CreateTypographyStyle();
// 设置段落样式的对齐方式为左对齐
OH_Drawing_SetTypographyTextAlign(typographyStyle, TEXT_ALIGN_LEFT);
