在一个简单的用户界面中，可能只需要展示几行静态文本，例如标签、按钮上的文字、菜单项或状态栏中的提示信息。此时，开发者只需要选择合适的字体、大小和颜色即可完成渲染。 此场景示例，涉及到的文本样式属性如下，具体及更多文本样式可参考 TextStyle 。 color：字体颜色，默认为白色。请注意与画布颜色进行区分，以保证文本的正常显示。 fontSize：字体大小，浮点数，默认为14.0，单位为物理像素px。 通过context获取到Canvas画布对象。 let canvas = context.canvas; 通过context获取到Canvas画布对象。 初始化文本样式，此处设置字体颜色为红色，字体大小为100px。 // 初始化文本样式
let myTextStyle: text.TextStyle = {
// 文本颜色
color: {
alpha: 255,
red: 255,
green: 0,
blue: 0
},
// 文本大小
fontSize: 100
}; 初始化文本样式，此处设置字体颜色为红色，字体大小为100px。 初始化段落样式。 let myParagraphStyle: text.ParagraphStyle = {
textStyle: myTextStyle,
}; 初始化段落对象，并添加文本。 let fontCollection = text.FontCollection.getGlobalInstance();
let paragraphBuilder = new text.ParagraphBuilder(myParagraphStyle, fontCollection);
// 更新文本样式
paragraphBuilder.pushStyle(myTextStyle);
// 添加文本
paragraphBuilder.addText("Hello World"); 排版段落并进行文本绘制。 // 生成段落
let paragraph = paragraphBuilder.build();
// 布局
paragraph.layoutSync(1250);
// 绘制文本
paragraph.paint(canvas, 0, 100);

在进行文本绘制时，可以通过选择合适的字体、大小和颜色完成简单文本的绘制与显示；此外，还支持通过设置其他丰富的样式、语言、段落等进行复杂文本的绘制。 多语言支持是全球化应用的基础。多语言文本绘制需要支持不同语言的字符集及其独特的显示需求，例如右到左语言（如阿拉伯语）或竖排文本（如中文）。开发者需要理解不同语言的渲染特性，确保文本的正确显示。 在多语言文本使用的场景下，主要通过指定 TextStyle 文本样式中的 locale 字段来实现，可直接通过locale字段的值优先匹配对应字体，跳过遍历列表匹配字体的过程，从而降低匹配时间和内存使用。 通过context获取到Canvas画布对象。 // 绘制代码逻辑写在这里
let canvas = context.canvas; 通过context获取到Canvas画布对象。 初始化文本样式。 let myTextStyle: text.TextStyle = {
color: {
alpha: 255,
red: 255,
green: 0,
blue: 0
},
fontSize: 50,
// 设置语言偏好为简体中文
locale: 'zh-Hans'
}; 初始化段落样式。 let myParagraphStyle: text.ParagraphStyle = {
textStyle: myTextStyle,
}; 初始化段落对象，并添加文本。 let fontCollection = text.FontCollection.getGlobalInstance();
let paragraphBuilder = new text.ParagraphBuilder(myParagraphStyle, fontCollection);
// 更新文本样式
paragraphBuilder.pushStyle(myTextStyle);
// 添加文本
paragraphBuilder.addText('你好，世界'); 排版段落并进行文本绘制。 // 生成段落
let paragraph = paragraphBuilder.build();
// 布局
paragraph.layoutSync(1250);
// 绘制文本
paragraph.paint(canvas, 10, 0);

在复杂的文本排版场景中，当系统提供的标准文本组件无法满足特定的视觉或交互需求时，开发者可以利用ArkGraphics 2D提供的底层文本绘制能力，通过直接控制画布（Canvas）和文本样式，实现对文本外观、布局的精细控制。这种能力适用于需要高度定制化文本渲染效果的场景，例如艺术字体、复杂的富文本编排或特殊的动态文字效果。 字体引擎作为图形系统中的核心组件，负责将字符代码转换为可视化的字形，并精确计算每个字形的布局和位置，为自定义文本绘制提供底层支持。通过文本测量接口，开发者可以获取文本的精确尺寸，这是实现精准布局（如居中显示）的基础。 文本塑形是字体引擎提供的一项关键能力，它允许开发者不经过系统默认的文本排版流程，直接获取文本的底层字形信息（如宽度、方向等测量信息）。这使得开发者能够基于这些原始数据，实现完全自定义的排版逻辑、绘制操作以及断行策略。 自定义富文本渲染：例如在社交媒体、新闻客户端等应用中，需要实现图文混排、多样式文本混合显示。 跨平台一致性排版需求应用：确保文本在不同平台或设备上呈现一致的视觉效果。 精细化排版管理：如实现艺术排版、动态文字布局等系统标准文本组件难以达到的效果。 文本塑形中常用接口如下表所示，详细接口说明参考 @ohos.graphics.text (文本模块) 和 TextBlob 。 从API version 18开始，支持获取文字塑形结果能力。从API version 20开始，支持获取文字排版方向和文字字形宽度。关键代码如下： 导入依赖的相关模块。 import { text } from '@kit.ArkGraphics2D'
import { drawing } from '@kit.ArkGraphics2D'
import { common2D } from '@kit.ArkGraphics2D' 创建段落样式，并使用构造段落生成器ParagraphBuilder生成段落实例。 let myTextStyle: text.TextStyle = {
// 文本大小
fontSize: 60
};
let myParagraphStyle: text.ParagraphStyle = {
textStyle: myTextStyle,
};
let fontCollection = text.FontCollection.getGlobalInstance();
let paragraphBuilder = new text.ParagraphBuilder(myParagraphStyle, fontCollection);

在一个简单的用户界面中，可能只需要展示几行静态文本，例如标签、按钮上的文字、菜单项或状态栏中的提示信息。此时，开发者只需要选择合适的字体、大小和颜色即可完成渲染。 创建Canvas画布对象，画布Canvas对象创建方法具体可见 画布的获取与绘制结果的显示 。 初始化段落样式，设置文本对齐方式为居中对齐。 // 创建一个 TypographyStyle 创建 Typography 时需要使用
OH_Drawing_TypographyStyle *typoStyle = OH_Drawing_CreateTypographyStyle();
// 设置文本对齐方式为居中
OH_Drawing_SetTypographyTextAlign(typoStyle, TEXT_ALIGN_CENTER); 初始化段落样式，设置文本对齐方式为居中对齐。 初始化文本样式，此处设置字体颜色为纯黑色，字体大小为60，字重为400。 // 设置文字颜色、大小、字重，不设置 TextStyle 会使用 TypographyStyle 中的默认 TextStyle
OH_Drawing_TextStyle *txtStyle = OH_Drawing_CreateTextStyle();
OH_Drawing_SetTextStyleColor(txtStyle, OH_Drawing_ColorSetArgb(0xFF, 0x00, 0x00, 0x00));
OH_Drawing_SetTextStyleFontSize(txtStyle, 60);
