}).catch((err: BusinessError) => {
hilog.error(0x0000, 'function', `Failed to call the function, code: ${err.code}, message: ${err.message}`);
}); 或者，使用callback异步回调： cloudFunction.call({
name: 'my-cloud-function', // my-clo

支持Phone、Tablet设备。并且从5.1.0(18)版本开始，新增支持Wearable设备；从5.1.1(19)版本开始，新增支持TV设备；从6.1.0(23)版本开始，新增支持PC/2in1设备。 将对象类型中导出的json格式文件命名为schema.json，拷贝到DevEco Studio项目的“AppScope/resources/rawfile”或者“entry/src/main/resources/rawfile”目录下。在编译构建过程中，AppScope目录下的资源文件会合入到模块的资源文件中，详细信息请参见 资源分类 。 按照AGC控制台上创建的对象类型“BookInfo”在代码工程“entry/src/main/ets/model”目录下创建BookInfo.ets文件，文件内容参考以下代码。 在AGC控制台创建的字段类型与ArkTS数据类型的匹配关系如下： String、Text对应string。 Boolean对应boolean。 Byte、ByteArray对应Uint8Array。 Short、Integer、Long、Float、Double、IntAutoIncrement、LongAutoIncrement对应number。 Date对应Date。 import { cloudDatabase } from '@kit.CloudFoundationKit';

class BookInfo extends cloudDatabase.DatabaseObject {
public naturalbase_ClassName(): string {
return 'BookInfo';
}

public id: number | undefined;
public bookName: string | undefined;
public author: string | undefined;
public price: number | undefined;
public borrowerId: number | undefined;
public borrowerName: string | undefined;
public borrowerTime: Date | undefined;
}

export { BookInfo };

支持Phone、Tablet设备。并且从5.1.0(18)版本开始，新增支持Wearable设备；从5.1.1(19)版本开始，新增支持TV设备；从6.1.0(23)版本开始，新增支持PC/2in1设备。 设置云数据库配置项。 在“entry/src/main/module.json5”文件中添加网络权限。 "requestPermissions": [
{
"name": "ohos.permission.INTERNET"
}
] 在“entry/src/main/module.json5”文件中添加网络权限。 （可选）如果存在需要登录应用才能操作数据库的场景（如新增或删除数据），您需要执行如下操作： 通过AuthProvider获取用户凭据 。 调用 init() 方法进行初始化时，传入获取的凭据。 （可选）如果存在需要登录应用才能操作数据库的场景（如新增或删除数据），您需要执行如下操作： 通过AuthProvider获取用户凭据 。 调用 init() 方法进行初始化时，传入获取的凭据。 导入相关模块。 import { cloudDatabase } from '@kit.CloudFoundationKit';
import { BookInfo } from '../model/BookInfo'; 在业务代码中，使用AGC开发平台上创建的存储区“QuickStartDemo”初始化DatabaseZone。 let databaseZone = cloudDatabase.zone('QuickStartDemo'); 后续“databaseZone”都需要在每个查询中独立使用，可以参考此章节创建，下文代码中不再重复创建的操作。 cloudDatabase.zone方法接收的入参为“存储区名称”，即cloudDBZoneName，请参见 新增存储区 章节。 存储区最多创建4个，超过4个会导致云数据库访问失败。 在业务代码中，使用AGC开发平台上创建的存储区“QuickStartDemo”初始化DatabaseZone。 后续“databaseZone”都需要在每个查询中独立使用，可以参考此章节创建，下文代码中不再重复创建的操作。

云数据库通过 query() 方法查询对象，并提供了丰富的谓词查询，比如 equalTo() 、 notEqualTo() 、 in() 等。通过单个或者多个链式过滤条件，开发者可以从存储区查询到满足特定条件的对象，也可以通过排序谓词对查询结果排序，或者通过限定查询返回数量谓词限定查询结果返回的数量。详细的查询条件请参见 DatabaseQuery 。 应用会直接从云侧存储区服务器查询数据，本地不会缓存数据。 每次的查询操作仅支持查询一个对象类型下的数据。 调用查询数据方法，有两种返回方式，返回一个Promise对象或者在参数中传入一个callback对象返回，下面以Promise为例详细说明。 支持Phone、Tablet设备。并且从5.1.0(18)版本开始，新增支持Wearable设备；从5.1.1(19)版本开始，新增支持TV设备；从6.1.0(23)版本开始，新增支持PC/2in1设备。 开发者可以在无查询条件时，获取一个对象类型中所有的对象；也可以指定单个查询条件，来获取满足该条件的对象。 导入相关模块。 import { cloudDatabase } from '@kit.CloudFoundationKit';
import { BookInfo } from '../model/BookInfo';
import { hilog } from '@kit.PerformanceAnalysisKit';
import { BusinessError } from '@kit.BasicServicesKit'; 查询对象类型BookInfo的所有数据。 let condition = new cloudDatabase.DatabaseQuery(BookInfo);
databaseZone.query(condition).then((resultArray: BookInfo[]) => {
resultArray.forEach((value) => {
hilog.info(0x0000, 'cloudDb',
`Succeeded in querying: bookName = ${value.bookName} price: ${value.price?.toString()}`);
});
}).catch((err: BusinessError) => {
hilog.error(0x0000, 'cloudDb', `Failed to query, code: ${err.code}, message: ${err.message}`);
});

开发者可以通过 upsert() 将一个或者一组对象写入到当前存储区中。在写入对象时，如果在存储区已经存在主键相同的对象，则更新已有的对象；如果不存在，则写入一个新的对象。写入的数据可以来自于新建对象，或者从存储区查询出来的对象。 写入一组对象时，数据的写入操作是原子性的，即对象列表中的对象要么全部成功写入，要么全部失败。 写入一组对象时，该组中的对象必须属于同一个对象类型，否则会导致写入失败。 写入一组对象时，数据总大小不能超过2MB，否则会导致写入失败。 写入一组对象时，数据总条数不能超过1000条，否则会导致写入失败。 写入一组对象时，“String”类型的数据最大长度为200个字符，“Text”类型的数据最大长度为100000000个字符。 调用写入数据方法，有两种返回方式，返回一个Promise对象或者在参数中传入一个callback对象返回，下面以Promise为例详细说明。 支持Phone、Tablet设备。并且从5.1.0(18)版本开始，新增支持Wearable设备；从5.1.1(19)版本开始，新增支持TV设备；从6.1.0(23)版本开始，新增支持PC/2in1设备。 Promise对象中封装了写入操作执行的结果，通过该Promise对象可以异步侦听执行结果：如果执行成功，可以获取写入的对象数量；如果执行失败，可以获取错误信息。 导入相关模块。 import { cloudDatabase } from '@kit.CloudFoundationKit';
import { BookInfo } from '../model/BookInfo';
import { hilog } from '@kit.PerformanceAnalysisKit';
import { BusinessError } from '@kit.BasicServicesKit'; 将BookInfo对象写入至存储区中，写入成功后，返回写入的数量；写入失败，抛出异常。 let book = new BookInfo();
book.id = 11;
book.bookName = 'Jane Eyre'
book.price = 100.0;
book.borrowerTime = new Date();
databaseZone.upsert(book).then((record: number) => {
hilog.info(0x0000, 'cloudDb', `Succeeded in upserting: ${record}`);
}).catch((err: BusinessError) => {
hilog.error(0x0000, 'cloudDb', `Failed to upsert, code: ${err.code}, messag

开发者可以通过 delete() 删除单个对象或者一组对象。删除数据时，云数据库会根据传入对象主键删除相应的数据，不会比对该对象其它属性与存储的数据是否一致。删除一组对象时，删除操作是原子性的，即对象列表中的对象要么全部删除成功，要么全部删除失败。 删除一组对象时，该组中的对象必须属于同一个对象类型，否则会导致删除失败。 调用删除数据方法，有两种返回方式，返回一个Promise对象或者在参数中传入一个callback对象返回，本文以Promise为例详细说明。 支持Phone、Tablet设备。并且从5.1.0(18)版本开始，新增支持Wearable设备；从5.1.1(19)版本开始，新增支持TV设备；从6.1.0(23)版本开始，新增支持PC/2in1设备。 导入相关模块。 import { cloudDatabase } from '@kit.CloudFoundationKit';
import { BookInfo } from '../model/BookInfo';
import { hilog } from '@kit.PerformanceAnalysisKit';
import { BusinessError } from '@kit.BasicServicesKit'; 将对象删除，如果删除成功，返回删除对象的个数；如果执行失败，抛出异常。 let book = new BookInfo();
book.id = 11;
databaseZone.delete(book).then((deleteNum: number) => {
hilog.info(0x0000, 'cloudDb', `Succeeded in deleting: ${deleteNum}`);
}).catch((err: BusinessError) => {
hilog.error(0x0000, 'cloudDb', `Failed to delete, code: ${err.code}, message: ${err.message}`);
}); 将对象删除，如果删除成功，返回删除对象的个数；如果执行失败，抛出异常。

支持Phone、Tablet设备。并且从5.1.0(18)版本开始，新增支持Wearable设备；从5.1.1(19)版本开始，新增支持TV设备；从6.1.0(23)版本开始，新增支持PC/2in1设备。 在“entry/src/main/module.json5”文件中添加网络权限。 "requestPermissions": [
