从6.1.1(24) 版本开始，支持管理用户授权。 应用拉起华为账号同步和授权界面，由用户授权相应的数据访问权限。用户可以自主选择授权的数据类型，可以只授权部分数据权限。应用所能操作的用户数据，是用户授权和运动健康服务审批通过的数据权限的交集。 常见问题请参考 Health Service Kit常见问题 。 导入运动健康服务功能模块。 import healthStore from '@hms.health.store'; 查询权限。 function getAuthorizations() {
let queryAuthorizationRequest = {
readDataTypes: [healthStore.healthDataTypes.WORKOUT_SUMMARY],
writeDataTypes: [healthStore.healthDataTypes.WORKOUT_SUMMARY],
scopes: ['https://www.huawei.com/healthkit/workout']
}

try {
let queryAuthorizationResponse = healthStore.getAuthorizations(queryAuthorizationRequest);
} catch (err) {
// 异常场景处理
}
} 发起用户授权请求。 function requestAuthorizations() {
let authorizationParameter = {
readDataTypes: [healthStore.healthDataTypes.WORKOUT_SUMMARY],
writeDataTypes: [healthStore.healthDataTypes.WORKOUT_SUMMARY],
scopes: ['https://www.huawei.com/healthkit/workout']
}
try {
let authorizationResponse = healthStore.requestAuthorizations(authorizationParameter);
} catch (err) {
// 异常场景处理
}
}

从6.1.1(24) 版本开始，支持运动联动管理。 运动联动管理包含运动联动的配置、开启、暂停、恢复、停止，数据订阅、取消订阅和下发融合数据，以及锻炼记录的读写。 需先通过 用户授权 接口引导用户授权，用户授权应根据 权限说明 中要求来打开锻炼记录读/写和联动接口控制权限，。 常见问题请参考 Health Service Kit常见问题 。 导入运动健康服务功能模块。 import healthService from '@hms.health.service';
import healthStore from '@hms.health.store'; 配置联动。 function config() {
let workoutOptions = {
linkageType: healthService.workout.LinkageType.ACTIVITY_LINK,
sportType: healthStore.exerciseSequenceHelper.badminton.EXERCISE_TYPE.id,
activityGoals: [
{
type: healthService.workout.TargetType.CALORIE,
value: 100
}
]
};
try {
healthService.workout.config(workoutOptions);
} catch (err) {
// 异常场景处理
}
} 开启联动。 function start() {
try {
let startResult = healthService.workout.start();
} catch (err) {
// 异常场景处理
}
} 暂停/恢复联动。 function pause() { // 暂停联动
try {
healthService.workout.pause();
} catch (err) {
// 异常场景处理
}
}

function resume() { // 恢复联动
try {
healthService.workout.resume();
} catch (err) {
// 异常场景处理
}
}

