// ...
}
// ...
}

Payment Kit服务提供了支付系统相关的一系列API接口。为减少API接口的接入工作量，提供了相应java版本的Maven依赖用于云侧服务对接。 开发者可通过Maven集成来完成服务器开发环境的构建，以此来快速使用华为支付提供的API接口。 可下载 示例代码-服务端 用以快速完成商户服务器接入。 因业务发展需要，API接口响应、通知回调请求字段可能会发生变动，如开发者自行实现验签逻辑，一定要使用原始的字符串转为Map对象进行验签处理后再转换成自定义的业务对象去使用，以确保验签正常通过。 商户使用提供的示例代码接入华为支付前请确保网络已正常连接，可以从华为支付仓库地址正常拉取Maven依赖。 在示例代码pom.xml文件中已配置仓库地址，如无法正常拉取依赖，可在Maven配置文件“settings.xml”中添加华为支付的Maven仓库地址。 在示例代码pom.xml文件中已引入jar包的Maven坐标。如商户自己构建工程则需在pom.xml文件中引入如下坐标： 将以下商户相关配置添加到示例代码配置文件src/main/resources/petalpayconfig.properties。 商户号，获取方式请参见 查询商户号信息 。 商户证书ID，获取方式请参见 上传商户证书 。 鸿蒙支付服务验签公钥，获取方式请参见 下载华为支付证书 。 鸿蒙支付服务加密公钥（非必选），涉及接口入参敏感字段（接口会做标注）加密时需配置，参见 敏感信息处理 。 商户号关联的APPID，获取方式请参见 AppID管理及关联 。 获取发起请求客户端对象 可通过工具类MercConfigUtil提供的方法getMercConfig快速获取PetalPayConfig对象来构建请求客户端，对应配置项获取及配置参见 配置初始化 。 // 商户配置
public static PetalPayConfig getMercConfig() {
return PetalPayConfig.builder().callerId(MERC_NO) // （必填）商户号
.appId(APP_ID) // （必填）商户号关联的APPID
.privateKey(MERC_PRIVATE_KEY) // （必填）商户私钥
.authId(MERC_AUTH_ID) // （必填）商户证书ID
.signType(SIGN_TYPE) // （选填）商户公私钥类型，默认RSA加密
.petalpayPublicKey(HW_PAY_PUBLIC_KEY_FOR_CALLBACK) // （非必填）验签公钥(和接口级配置needVerifyRsp对应，公钥和商户通知回调验签公钥同一个)
.domainHost(SERVER_HOST).build();
} 方式一 ：使用默认实现的请求客户端工具类

商户客户端根据Payment Kit接口返回的支付信息 PayResult (混合支付场景）/ PickerResult （纯外部支付场景），按照三方支付平台接入要求创建订单获取拉起三方支付收银台链接并构建 订单支付跳转信息 orderStr 请求 requestPayment 接口跳转或拉起三方支付收银台。 跳转三方支付收银台示例代码如下： import { BusinessError } from '@kit.BasicServicesKit';
import { paymentService } from '@kit.PaymentKit';
import { common } from '@kit.AbilityKit';

@Entry
@Component
struct Index {
context: common.UIAbilityContext = this.getUIContext().getHostContext() as common.UIAbilityContext;
requestPaymentPromise() {
// 请使用开发者自己的订单信息（orderStr），跳转三方支付方式。
const orderStr = '{"nextAction":"L","linkUrl":"","scheme":"","clientToken":"***"}';
paymentService.requestPayment(this.context, orderStr, 'AP')
.then((payResult: paymentService.PayResult) => {
// 支付成功
console.info('succeeded in paying, pay result: ', payResult);
})
.catch((error: BusinessError) => {
// 支付失败
console.error(`failed to pay, error.code: ${error.code}, error.message: ${error.message}`);
});
}

build() {
Column() {
Button('requestPaymentPromise')
.type(ButtonType.Capsule)
.width('50%')
.margin(20)
.onClick(() => {
this.requestPaymentPromise();
})
}
.width('100%')
.height('100%')
}
}

