},
'film': {
'type': 'string',
'description': '目标电影名称，需为当前上映或即将上映且在影院排片列表中的电影'
},
'time': {
'type': 'string',
'description': '放映时间，必须为未来的场次，且需为影院当天有效排片时间；时间格式应为\'YYYY-MM-DD HH:MM\'（例如\'2025-07-01 19:30\'）'
}
},
