"./src/main/ets/Test.ets"
]
}
}
}
} 当前模块的build-profile.json5文件中需进行以下配置： 使用napi_load_module_with_info加载Test文件，调用函数test以及获取变量value。 开启useNormalizedOHMUrl后（即将工程目录中与entry同级别的应用级build-profile.json5文件中strictMode属性的useNormalizedOHMUrl字段配置为true），加载模块内文件路径时： bundleName不会影响最终加载逻辑，会智能通过module名索引进程内对应的hap，例如：工程的bundleName为com.example.application，实际入参时填写为 com.example.application1，模块也能正常加载。 路径需要以packageName开头，packageName指的是模块的oh-package.json5中配

Node-API中的napi_call_threadsafe_function_with_priority接口的功能是从异步线程向ArkTS线程投递指定优先级和入队方式的任务，底层队列会根据任务的优先级和入队方式来处理任务。 异步线程向ArkTS主线程中投递的任务需要根据任务指定的优先级和入队方式进行处理。 功能实现 #include "napi/native_api.h"
// ...
#include <hilog/log.h>
// ...
static constexpr int INT_ARG_2 = 2; // 入参索引
static constexpr int INT_ARG_12 = 12; // 入参索引
static constexpr int INT_ARG_15 = 15; // 入参索引
// ...
struct CallbackData {
napi_threadsafe_function tsfn;
napi_async_work work;
};
static void CallJs(napi_env env, napi_value jsCb, void *context, void *data)
{
if (env == nullptr) {
return;
}

napi_handle_scope scope = nullptr;
napi_status status = napi_open_handle_scope(env, &scope);
if (status != napi_ok) {
return;
}

napi_value resultNumber = nullptr;
napi_value undefined = nullptr;
napi_get_undefined(env, &undefined);
napi_value number1 = nullptr;
napi_create_int32(env, INT_ARG_12, &number1);
napi_value number2 = nullptr;
napi_create_int32(env, INT_ARG_15, &number2);
napi_value argv[2] = {number1, number2};
napi_call_function(env, undefined, jsCb, INT_ARG_2, argv, &resultNumber);
int32_t res = 0;
// 获取resultNumber对应的int32值
napi_get_value_int32(env, resultNumber, &res);

napi_close_handle_scope(env, scope);
}

// 异步线程中调

HarmonyOS提供的API优化了强引用的创建效率，保留了Node-API的强引用特性，相较于napi_ref，napi_strong_ref具有更快的创建效率。 开发者可以通过napi_create_strong_reference接口创建指向ArkTS对象的强引用，并通过napi_get_strong_reference_value获取引用的ArkTS对象。 模块注册 // napi_init.cpp
#include "napi/native_api.h"
#include <vector>

// napi_strong_ref 不支持跨线程使用。示例为单线程场景。请勿在业务代码中使用此方式声明。
static napi_strong_ref g_strongRef {};
static napi_value NAPI_Global_saveOrReplaceObject(napi_env env, napi_callback_info info)
{
napi_value args[1]{};
size_t argc = 1;
napi_get_cb_info(env, info, &argc, args, /* thisVar */ nullptr, /* data */ nullptr);
if (argc < 1) {
return nullptr;
}

if (g_strongRef != nullptr) {
napi_delete_strong_reference(env, g_strongRef);
g_strongRef = nullptr;
}
napi_create_strong_reference(env, args[0], &g_strongRef);
return nullptr;
}

static napi_value NAPI_Global_releaseObject(napi_env env, [[maybe_unused]] napi_callback_info info)
{
if (g_strongRef != nullptr) {
napi_delete_strong_reference(env, g_strongRef);
g_strongRef = nullptr;
}
return nullptr;
}

static napi_value NAPI_Global_queryObject(napi_env env, [[maybe_unused]] napi_callback_info info)
{
napi_value result {};
napi_get_strong_reference_value(env, g_strongRef, &result);
return result;
}

Node-API扩展接口napi_open_critical_scope用于打开临界区作用域，napi_close_critical_scope用于关闭临界区作用域。 非临界接口不能在临界区作用域使用，且同一执行环境中只能打开一个临界区作用域。建议仅在需要临界接口时打开临界区作用域，使用后应及时关闭。 调用临界接口前，必须通过napi_open_critical_scope打开临界区作用域，并在临界区作用域内进行调用。 关闭临界区作用域后，请勿使用临界接口及其返回结果，否则可能导致程序崩溃或数据损坏。 1.当ArkTS String以UTF-16编码存储时，napi_get_buffer_string_utf16_in_critical_scope才能正确获取其内存缓冲区，否则该函数返回错误。 2.napi_create_string_utf16和napi_create_string_utf8的功能是将输入数据以指定编码传递给虚拟机。这些函数不控制字符串在虚拟机的内部存储编码方式。 模块注册 // napi_init.cpp
#include <string>
#include <string_view>
#include <vector>

#include "napi/native_api.h"

// 使用C++的RAII机制管理临界区作用域，避免遗漏关闭
// 仅用作示例，也可以通过其他方式进行封装，或直接使用原始接口
class MyCriticalScope
{
napi_env env_{};
napi_critical_scope scope_{};

public:
explicit MyCriticalScope(napi_env env) : env_(env)
{
if (napi_open_critical_scope(env, &scope_) != napi_ok)
{
// 失败时，进行一些必要的错误处理，或维护信息补充，此处省略。
// 常见失败原因：env不是有效的Node-API执行上下文（如：env参数为nullptr）
}
}
~MyCriticalScope()
{
Close();
}
inline void Close()
{
if (scope_ == nullptr)
{
return;
}
// 在析构函数中，关闭临界区作用域
if (napi_close_critical_scope(env_, scope_) != napi_ok)
{
// 失败时，进行一些必要的错误处理，或维护信息补充，此处省略。
// 常见失败原因：
// 1. 重复关闭临界区作用域。
// 2. env不是有效的Node-API执行上下文（如：空指针）。
// 3. scope不是有效的临界区作用域句柄（如：空指针）。
}
