napi_get_value_string_utf8(env, error, errorMsg, sizeof(errorMsg) - 1, &len);
errorMsg[len] = '\0';
OH_LOG_ERROR(LOG_APP, "Promise rejected with error:%{public}s", errorMsg);
return nullptr;
}

